INSERT INTO spells (id, name, school, subschool, descriptor, level, type, class_lists, casting_time, range, target, area, effect, duration, saving_throw, spell_resistance, description, material, arcane_focus, divine_focus, costly_components)
VALUES
  ('unliving_rage', 'Unliving Rage', 'necromancy', NULL, NULL, 2, 'both', 'mesmerist 2, cleric 2, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, 'concentration + 1 round/level (D)', 'none', 'yes', 'This spell functions as rage, except it affects only undead creatures and bolsters them with necromantic energy rather than emotion. Each affected creature gains a +2 profane bonus to Strength and Charisma, a +1 profane bonus on Will saves, and a –2 penalty to AC. The effect is otherwise identical to a barbarian’s rage.', NULL, NULL, false, false),
  ('unlock_flesh', 'Unlock Flesh', 'necromancy', NULL, NULL, 1, 'arcane', 'sorcerer/wizard 1, witch 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level (living creature) or instantaneous (undead target); see below', 'Fort negates', 'yes', 'By touching a creature with a bladed instrument, you cause the creature’s flesh to loosen and slide against its skeletal moorings. A living creature touched becomes staggered by the disturbing and uncomfortable sensation for 1 round per level. Each round on its turn, the subject can attempt a new saving throw to end the effect. This is a standard action that does not provoke attacks of opportunity. A corporeal undead creature targeted by this spell instead takes 1d6 points of damage per caster level (maximum 5d6 at 5th level) as wet, oozing chunks of flesh slough off its desiccated bones (a successful Fortitude save halves this damage). Incorporeal creatures, or creatures that do not have flesh, are immune to this spell’s effects.', NULL, 'any slashing weapon or cutting tool', false, false),
  ('unnatural_lust', 'Unnatural Lust', 'enchantment', 'compulsion', 'emotion, mind-affecting', 1, 'arcane', 'bard 1, mesmerist 1, psychic 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round', 'Will negates', 'yes', 'Your target is filled with lust and desire for a single creature or object as designated by you at the time of casting. That creature or object must be within the spell’s range and perceivable by the target of the spell. The target is filled with the compulsion to rush to the subject of its lust and passionately kiss or caress that subject on its next turn, taking no other actions. If the target would not normally have lustful feelings toward the designated creature or object, it receives a +4 bonus on its saving throw.', NULL, NULL, false, false),
  ('unprepared_combatant', 'Unprepared Combatant', 'enchantment', 'compulsion', 'emotion, mind-affecting', 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'The target takes a –4 penalty on initiative checks and Reflex saves.', NULL, NULL, false, false),
  ('unravel_destiny', 'Unravel Destiny', 'divination', NULL, NULL, 3, 'both', 'cleric/oracle 3, sorcerer/wizard 3, witch 3', '1 standard action', 'short (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'Note: This spell deals with hero points. See Hero Points for full details.', NULL, NULL, true, false),
  ('unseen_crew', 'Unseen Crew', 'conjuration', 'creation', NULL, 4, 'arcane', 'bard 4, sorcerer/wizard 5, summoner 5, witch 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'one invisible sailor per level', '1 day/level', 'none', 'no', 'An unseen crew member is an invisible, shapeless force that performs the duties of one crew member. It can tie off ropes, hoist sails, swab decks, and other such duties. An unseen crew member possesses no other skills. It cannot fight, speak, or even defend itself.', NULL, NULL, false, false),
  ('unseen_engineers', 'Unseen Engineers', 'conjuration', 'creation', NULL, 2, 'arcane', 'sorcerer/wizard 3, summoner 2, witch 3', '1 standard action', 'long (400 ft. + 40 ft. level)', NULL, NULL, 'a team of tiny, invisible engineers', '1 minute/level', 'none', 'no', 'You conjure an invisible team of tiny engineers to construct a trap at alarming speed. Originating at your location, the team must remain within range of you or the spell ends. The engineers construct a mechanical trap of your choice. Construction takes a number of rounds equal to the trap’s challenge rating. The engineers must have the materials available. At the end of the construction time, use your Craft(traps) skill with a +5 bonus to determine the success of their work. If the engineers succeed, the trap is complete and the spell ends. If they fail, the materials are deposited at that location and the spell ends. If the spell’s duration ends before the trap is complete, the engineers automatically fail.', 'materials required to construct the trap', NULL, false, false),
  ('unseen_servant', 'Unseen Servant', 'conjuration', 'creation', NULL, 1, 'arcane', 'bard 1, magus 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1, witch 1; Mystery ancestor 1, occult 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'one invisible, mindless, shapeless servant', '1 hour/level', 'none', 'no', 'An unseen servant is an invisible, mindless, shapeless force that performs simple tasks at your command. It can run and fetch things, open unstuck doors, and hold chairs, as well as clean and mend. The servant can perform only one activity at a time, but it repeats the same activity over and over again if told to do so as long as you remain within range. It can open only normal doors, drawers, lids, and the like. It has an effective Strength score of 2 (so it can lift 20 pounds or drag 100 pounds). It can trigger traps and such, but it can exert only 20 pounds of force, which is not enough to activate certain pressure plates and other devices. It can’t perform any task that requires a skill check with a DC higher than 10 or that requires a check using a skill that can’t be used untrained. This servant cannot fly, climb, or even swim (though it can walk on water). Its base speed is 15 feet.', 'a piece of string and a bit of wood', NULL, false, false),
  ('unsettling_presence', 'Unsettling Presence', 'necromancy', 'haunted', 'emotion, fear, mind-affecting', 1, 'both', 'bard 2, medium 1, mesmerist 2, occultist 2, psychic 2, shaman 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, 'one 5-ft. cube/level (S)', NULL, '1 hour/level (D)', 'Will negates', 'yes', 'Those in this spell’s area who fail their Will saving throws harbor a faint sense of paranoia and evoke the same feeling in others for the duration of the spell. Domesticated animals (not including familiars and animal companions) don’t willingly approach affected creatures unless the animal’s master succeeds at a DC 25 Handle Animal, Ride, or wild empathy check. Affected creatures take a –4 penalty on Handle Animal, Ride, and wild empathy checks against familiars, animal companions, animal cohorts, and other permanent companions provided by class abilities for the spell’s duration. Anyone an affected creature interacts with must succeed at a Will save or have its initial attitude automatically worsened by one step for the spell’s duration.', NULL, NULL, false, false),
  ('unshakable_chill', 'Unshakable Chill', 'necromancy', NULL, 'cold', 2, 'both', 'bloodrager 2, druid 2, sorcerer/wizard 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '10 minutes/level; see text', 'Fortitude negates (see text)', 'yes', 'The target is filled with an unshakable chill for the duration of the spell, and suffers from the effects of severe cold.', NULL, NULL, false, false),
  ('unshakable_zeal', 'Unshakable Zeal', 'enchantment', 'compulsion', 'emotion, mind-affecting', 5, 'both', 'bard 5, inquisitor 6, psychic 7, spiritualist 6', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'yes (harmless)', 'You fill the target with boundless enthusiasm and faith in its ultimate triumph. Whenever the target fails an attack roll, a save, a skill check, a concentration check, or an ability check, the target receives a +4 morale bonus on its next attempt at the failed check within 1 round (this includes attack rolls against the same foe, saving throws against the same ability from the same foe, and so on). In addition, when the target would be affected by a fear or emotion effect, it can instead dismiss unshakable zeal without spending an action to negate the effect on itself.', NULL, 'a silver circlet', false, false),
  ('unspoken_name', 'Unspoken Name', 'divination', NULL, NULL, 3, 'both', 'cleric 3, inquisitor 3, sorcerer/wizard 3, witch 3', '1 minute', 'personal', 'you', NULL, NULL, '24 hours or until discharged', NULL, NULL, 'When you cast this spell, designate a word, phrase, or name. If a creature within 1 mile of you uses that word, phrase, or name to refer to you, you immediately learn that creature’s name, appearance, and location. This discharges the spell.', NULL, NULL, false, false),
  ('untold_wonder', 'Untold Wonder', 'enchantment', 'compulsion', 'mind-affecting', 3, 'both', 'bard 4, cleric 5, mesmerist 4, paladin 3, psychic 5, sorcerer/ wizard 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '10 minutes/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You fill the target’s mind with childlike wonder, allowing that creature to marvel at things that would be debilitating to others.', NULL, NULL, false, false),
  ('unwelcome_halo', 'Unwelcome Halo', 'evocation', NULL, 'light', 1, 'both', 'cleric/oracle 1, paladin 1, sorcerer/wizard 1', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'one nongood creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'This spell causes the target to glow as if surrounded by a halo of light. This halo sheds normal light in a 20-foot radius from the creature, and increases the light level by one step for an additional 20 feet. This halo makes it impossible for the creature to gain concealment in non-magical darkness, and in dim or darker conditions, the creature’s glow can be seen even if it is not within direct line of sight.', NULL, NULL, false, false),
  ('unwilling_shield', 'Unwilling Shield', 'necromancy', NULL, NULL, 5, 'both', 'bard 5, inquisitor 5, sorcerer/wizard 6, witch 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level (D)', 'Will negates', 'yes', 'Like shield other, unwilling shield creates a mystic connection between you and the target, but unlike shield other, the target shares the wounds that you receive. In addition, the link draws upon the target’s life force to supplement your own defenses. You gain a +1 luck bonus to AC and on saving throws. You take only half damage from all wounds and attacks (including those dealt by special abilities) that deal hit point damage. The amount of damage not taken by you is taken by the target. Forms of harm that do not involve hit points, such as charm effects, ability damage, level draining, and death effects are not affected. If you take a reduction in hit points from a lowered Constitution score, the reduction is not split with the target because it is not hit point damage.', 'ruby dust worth 250 gp', NULL, false, true),
  ('unwitting_ally', 'Unwitting Ally', 'enchantment', 'charm', 'mind-affecting', 0, 'arcane', 'bard 0, psychic 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round', 'Will negates', 'yes', 'You befuddle the target’s mind. The target has difficulty telling friend from foe for a short period of time. The subject is considered your ally and not your enemies’ ally while determining flanking. The subject takes no other hostile action against your enemies due to this spell’s effect.', NULL, NULL, false, false),
  ('urban_grace', 'Urban Grace', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, ranger 1, sorcerer/wizard 1, witch 1', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'You become one with the city around you, allowing you to move more easily through its crowds and buildings. For the duration of this spell, your base land speed increases by 10 feet. In addition, it does not cost you 2 squares of movement to enter a square with crowds, though the crowd still provides cover to you. This ability does not allow you to enter the space of enemy creatures without making the appropriate Acrobatics check. In addition, you receive a +4 circumstance bonus on Acrobatics checks made to move across uneven urban surfaces, such as roofs and broken pavement, and on Climb checks made to scale walls and other artificial surfaces. Whenever you make an Acrobatics check to make a long jump between two buildings or artificial structures, you are always treated as if you had a running start, regardless of the actual distance traveled.', NULL, NULL, false, false),
  ('urban_step', 'Urban Step', 'conjuration', 'teleportation', NULL, 2, 'arcane', 'bard 2, magus 3, occultist 3, sorcerer/wizard 3, summoner 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', 'two doors or other portals in range', NULL, NULL, '1 round', NULL, NULL, 'You set up a magical connection between two doors (or other physical portals, such as windows) that both must be within range, line of sight, and line of effect. During the spell’s duration, you can move through one of the two portals. When you do, you teleport to the other portal, emerging in either direction. Both portals must be open and unobstructed when you cast the spell and enter the first portal, and they both must be large enough for you to fit through, otherwise the spell ends and the teleportation fails. You can bring along objects as long as their combined weight doesn’t exceed your maximum load.', 'scrap of cobweb', NULL, false, false),
  ('utter_contempt', 'Utter Contempt', 'enchantment', NULL, 'emotion', 3, 'both', 'antipaladin 3, bard 4, sorcerer/wizard 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You fill the target’s heart with malice for all other creatures. The target’s attitude toward all creatures other than itself worsens by two steps.', 'spittle', NULL, false, false),
  ('vacuous_vessel', 'Vacuous Vessel', 'illusion', 'glamer', NULL, 0, 'arcane', 'bard 0, sorcerer/wizard 0', '1 swift action', 'touch', 'container touched', NULL, NULL, '1 round/level (D)', 'Will negates; see text', 'yes; see text', 'This spell makes a single bag, chest, sack, or other container look and feel empty. The container must be no larger than 1 cubic foot per caster level or the spell fails. Anyone peering into or reaching into the container must succeed at a Will save or perceive the container as being completely empty. All items within the container when the spell was cast are still present, but they can’t be noticed unless removed from the bag—such as by someone who can perceive them, or who upends the container.', NULL, NULL, false, false),
  ('vampiric_hunger', 'Vampiric Hunger', 'necromancy', 'polymorph', 'evil', 3, 'both', 'antipaladin 3, cleric 3, druid 3, sorcerer/wizard 3, witch 3', '1 round', 'touch', 'one creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'The target of this spell grows the fangs of a vampire, as well as a thirst for blood. For the duration of this spell, the target gains the ability to drain an opponent’s blood during a grapple; if the target establishes or maintains a pin, it drains blood, dealing 1d4 points of Constitution damage. Each round it drains blood in this way, the target heals 5 hit points or gains 5 temporary hit points for the duration of the spell (up to a maximum number of temporary hit points equal to its full normal hit points). If the target does not drain blood in this way while under the effects of this spell, it becomes exhausted at the end of the spell’s duration.', NULL, NULL, false, false),
  ('vampiric_shadow_shield', 'Vampiric Shadow Shield', 'necromancy', NULL, NULL, 5, 'arcane', 'magus 5, sorcerer/wizard 5; Mystery shadow 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'This spell wreathes you in shadowy energy and damages those that make melee attacks against you. Any creature that strikes you with its body or a handheld weapon deals normal damage, but at the same time the attacker takes 1d6 points of negative energy damage + 1 point per caster level (maximum +15). If the attacker has spell resistance, it applies to this effect. Creatures wielding melee weapons with reach are not subject to this damage. When an attacker takes damage from the spell, you heal a number of hit points equal to 25% of the damage the spell dealt.', NULL, NULL, false, false),
  ('vampiric_touch', 'Vampiric Touch', 'necromancy', NULL, NULL, 3, 'both', 'antipaladin 3, bloodrager 3, magus 3, medium 3, mesmerist 3, psychic 3, sorcerer/wizard 3, spiritualist 3, witch 3; Subdomain blood 3, daemon 3; Bloodline daemon 3, ghoul 3', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous/1 hour; see text', 'none', 'yes', 'You must succeed on a melee touch attack. Your touch deals 1d6 points of damage per two caster levels (maximum 10d6). You gain temporary hit points equal to the damage you deal. You can’t gain more than the subject’s current hit points + the subject’s Constitution score (which is enough to kill the subject). The temporary hit points disappear 1 hour later.', NULL, NULL, false, false),
  ('vanish', 'Vanish', 'illusion', 'glamer', NULL, 1, 'arcane', 'bard 1, magus 1, psychic 1, sorcerer/wizard 1', '1 standard action', 'touch', NULL, NULL, NULL, '1 round/level (up to 5 rounds) (D)', 'Will negates (harmless)', 'yes (harmless)', 'This spell functions like invisibility, except the effect only lasts for 1 round per caster level (maximum of 5 rounds). Like invisibility, the spell immediately ends if the subject attacks any creature.', NULL, NULL, false, false),
  ('veil', 'Veil', 'illusion', 'glamer', NULL, 6, 'arcane', 'bard 6, sorcerer/wizard 6; Subdomain ambush 6; Bloodline  aberrant 6', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, 'concentration + 1 hour/level (D)', 'Will negates; see text', 'yes; see text', 'You instantly change the appearance of the subjects and then maintain that appearance for the spell’s duration. You can make the subjects appear to be anything you wish. The subjects look, feel, and smell just like the creatures the spell makes them resemble. Affected creatures resume their normal appearances if slain. You must succeed on a Disguise check to duplicate the appearance of a specific individual. This spell gives you a +10 bonus on the check.', NULL, NULL, false, false),
  ('veil_of_ash', 'Veil of Ash', 'evocation', NULL, 'fire', 2, 'arcane', 'sorcerer/wizard 2', '1 standard action', 'close (25 f. + 5f./2 levels)', 'one creature', NULL, NULL, '1 round/level', 'Fortitude negates', 'yes', 'This spell causes a small cloud of searing, choking ash to appear around the face of the target.', 'a pinch of ash', NULL, false, false),
  ('veil_of_heaven', 'Veil of Heaven', 'abjuration', NULL, 'good', 1, 'divine', 'paladin 1', '1 standard action', 'personal or 5 ft.; see text', 'you or all creatures within 5 ft.; see text', NULL, NULL, '10 minutes/level (D)', 'Will half', 'none', 'You surround yourself with a veil of positive energy, making it harder for evil outsiders to harm you. For the duration of this spell, you gain a +2 sacred bonus to AC and on saves. Both of these bonuses apply only against attacks or effects created by outsiders with the evil subtype. You can dismiss this spell as a swift action to deal 1d8 points of damage + 1 point per paladin level to all such outsiders within 5 feet. A Will save halves this damage.', NULL, NULL, true, false),
  ('veil_of_positive_energy', 'Veil of Positive Energy', 'abjuration', NULL, 'good', 1, 'divine', 'paladin 1', '1 standard action', 'personal or 5 ft.; see text', NULL, NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'You surround yourself with a veil of positive energy, making it harder for undead creatures to harm you. When under the effect of this spell, you gain a +2 sacred bonus to AC and a+2 sacred bonus on saves. Both of these bonuses apply only against attacks or effects created by undead creatures. You can dismiss this spell before its normal duration as a swift action on your turn to deal a number of points of positive energy damage equal to your level to all undead creatures within 5 feet of you.', NULL, NULL, true, false),
  ('vengeful_comets', 'Vengeful Comets', 'evocation', NULL, 'cold', 3, 'both', 'druid 3, sorcerer/wizard 3', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, '1 comet per 4 levels', '1 round/level or until completely discharged (see below)', 'none', 'yes', 'This spell causes a number of miniature comets (up to one per four caster levels) to orbit in the air above your head. Bits of snow and cold wind drift down from the orbiting comets, granting you a circumstance bonus equal to the number of comets on all saving throws against fire effects.', NULL, NULL, false, false),
  ('vengeful_outrage', 'Vengeful Outrage', 'enchantment', 'compulsion', 'emotion, language- dependent, mind-affecting', 5, 'arcane', 'bard 5, sorcerer/wizard 6, witch 6', '1 round', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates', 'yes', 'You place a magical command upon a creature to seek out and destroy a single enemy that has inflicted some perceived or actual harm to the target. You designate the enemy at the time of casting, which must be known by the target (such as “your brother’s murderer”) or can easily identify by sight (such as “the hill giant king”). The target is under the effect of a geas to find and capture or kill this enemy, and the target takes the penalties of that spell as long as it is not actively trying to reach the enemy. When the target enters combat with the enemy, it gains a +6 morale bonus to Strength and Constitution, a +3 morale bonus on Will saves, and is immune to the shaken and frightened conditions.', NULL, NULL, false, false),
  ('vengeful_stinger', 'Vengeful Stinger', 'transmutation', 'polymorph', 'poison', 5, 'both', 'cleric/oracle 6, shaman 5, sorcerer/wizard 5, summoner 5, witch 5', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', 'Fort negates; see text', 'no', 'You grow a long, wasp-like tail complete with stinger that can strike those who dare attack you. While you are under the effects of this spell, when a creature adjacent to you hits you with a melee attack, you can make an attack of opportunity with your stinging tail, even if your opponent’s attack would not otherwise provoke an attack of opportunity. You must otherwise be eligible to make an attack of opportunity to use this ability. The attack is made with your full attack bonus, and with a +2 sacred bonus on the attack roll. The stinging tail is considered a light weapon with a critical range of 19–20/×2. On a successful hit, the target takes 1d8 points of damage plus an amount of damage equal your Strength modifier and must succeed at a Fortitude save or it takes 1d4 points of Dexterity damage. This poison damage is also modified on a confirmed critical hit.', 'a living wasp', NULL, true, false),
  ('venomous_bite', 'Venomous Bite', 'transmutation', NULL, 'poison', 2, 'both', 'alchemist 2, druid 2, ranger 2, shaman 2, summoner 2, witch 2', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'a vial of injury poison worth at least 75 gp', NULL, true, true),
  ('venomous_bolt', 'Venomous Bolt', 'necromancy', NULL, 'poison', 3, 'divine', 'ranger 3', '1 swift action', '0 ft.', NULL, NULL, NULL, 'instantaneous', 'Fortitude negates; see text', 'yes', 'You infuse a single arrow or crossbow bolt with natural venom as you fire it. In addition to its normal damage, anyone struck by this arrow or bolt is affected as if by the poison spell. If the arrow is not fired immediately, the spell ends with no effect.', NULL, NULL, false, false),
  ('venomous_promise', 'Venomous Promise', 'transmutation', NULL, 'language-dependent, poison', 3, 'both', 'antipaladin 3, bard 3, mesmerist 3, shaman 3, witch 3', '1 standard action', 'touch', 'one creature', NULL, NULL, 'permanent or until triggered', 'yes', 'yes', 'You guard your words and person with poisonous power. You can impart a short amount of information—up to 25 words—as you cast this spell, entwining your words with the poison provided as a material component. If your target reveals the information you impart (verbally, in writing, with gestures, or by having its mind read with spells like detect thoughts), the target is immediately exposed to the poison (and is allowed any saving throw the poison allows).', 'a vial of poison', NULL, false, false),
  ('ventriloquism', 'Ventriloquism', 'illusion', 'figment', NULL, 1, 'arcane', 'bard 1, psychic 1, sorcerer/wizard 1, summoner/unchained summoner 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'intelligible sound, usually speech', '1 min./level (D)', 'Will disbelief (if interacted with)', 'no', 'You can make your voice (or any sound that you can normally make vocally) seem to issue from someplace else. You can speak in any language you know. With respect to such voices and sounds, anyone who hears the sound and rolls a successful save recognizes it as illusory (but still hears it).', NULL, 'parchment rolled into cone', false, false),
  ('vermin_shape', 'Vermin Shape', 'transmutation', 'polymorph', NULL, 3, 'both', 'alchemist 4, bloodrager 4, druid 3, magus 4, sorcerer/wizard 4, witch 3; Mystery outer rifts 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level', NULL, NULL, 'When you cast this spell, you assume the form of any Small or Medium creature of the vermin type. If the form you assume has any of the following abilities, you gain the listed ability: climb 30 feet, fly 30 feet (average maneuverability), swim 30 feet, darkvision 60 feet, low-light vision, scent, and lunge. You don’t gain full immunity to mind-affecting effects, but you do gain a +2 resistance bonus on all saving throws against such effects.', 'a piece of the creature whose form you plan to assume', NULL, false, false),
  ('verminous_transformation', 'Verminous Transformation', 'transmutation', 'polymorph', NULL, 6, 'both', 'alchemist 6, shaman 7, witch 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'You partially transform your body into a swarm of bats, insects, rats, and spiders. As a standard action, you can send out a piece of your body to attack up to four Medium or smaller creatures (or one larger creature) within 10 feet of you. The creatures take 4d6 points of damage and must succeed at a Fortitude save or take 1d3 points of Constitution damage and 1d3 points of Strength damage; the ability damage is a poison effect. Abilities that protect against swarm attacks apply to this damage and spell resistance applies.', 'a handful of bat wings, insects, and rat tails', NULL, false, false),
  ('versatile_weapon', 'Versatile Weapon', 'transmutation', NULL, NULL, 2, 'both', 'bard 2, bloodrager 3, ranger 2, magus 3, occultist 2, psychic 3, sorcerer/wizard 3; Elemental School metal 3; Mystery metal 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You transform the physical makeup of a weapon as you desire.', 'iron filings', NULL, false, false),
  ('vestment_of_the_champion', 'Vestment of the Champion', 'abjuration', NULL, NULL, 2, 'divine', 'antipaladin 2, paladin 2', '1 standard action component V, S', 'touch', 'armor or shield touched', NULL, NULL, '1 minute/level', 'none', 'no', 'This functions as magic vestment, except it only affects armor or a shield you are wearing or carrying. If the armor or shield is worn or carried by anyone other than you, the spell has no effect, but resumes its effect when you are wearing or carrying it again.', NULL, NULL, false, false),
  ('vex_giant', 'Vex Giant', 'transmutation', NULL, NULL, 3, 'divine', 'ranger 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round per level', NULL, NULL, 'When you cast vex giant, your senses and reflexes become particularly honed against a single target within 60 feet, provided the target is at least one size category larger than you. You may select your focused foe as a free action when you cast this spell—switching your focus to a different foe within 60 feet is a move action. If a foe moves beyond 60 feet from you, you lose your focus on that foe, although you may regain it by moving within 60 feet and spending a move action. Although the name of the spell is vex giant, it works equally well on any foe that’s at least one size category larger than you.', 'a fragment from a Large or larger weapon', NULL, false, false),
  ('vexing_miscalculation', 'Vexing Miscalculation', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'cleric/oracle 2, inquisitor 2, witch 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level or until discharged', 'Will negates', 'yes', 'You frustrate an opponent with ill fortune that leads even its most accurate attacks astray. The target is unable to score critical threats for the duration of this spell, even if the result of its roll would normally be a critical threat. If the creature rolls a natural 20, the attack still hits regardless of its opponent’s AC, but the hit is not eligible for a critical confirmation roll. Once a critical threat has been foiled by vexing miscalculation, the spell is discharged.', NULL, NULL, false, false),
  ('vicarious_view', 'Vicarious View', 'divination', 'scrying', NULL, 3, 'both', 'bard 4, medium 3, mesmerist 4, occultist 4, psychic 4, shaman 4, sorcerer/wizard 4, spiritualist 4, witch 4', '1 standard action', 'touch', NULL, NULL, 'magical sensor', '1 minute/level (D)', 'Will negates (object)', 'yes (object)', 'You plant a scrying sensor on a touched creature, object, or point in space, allowing you to see and hear the creature, object, or point and its surroundings (approximately 10 feet in all directions). If the creature or object on moves, the sensor moves with it. Unlike other scrying spells, vicarious view doesn’t allow magically or supernaturally enhanced senses to work through it.', NULL, NULL, false, false),
  ('vigilant_rest', 'Vigilant Rest', 'abjuration', NULL, NULL, 3, 'both', 'antipaladin 3, bard 4, medium 3, mesmerist 4, occultist 3, paladin 3, psychic 4, ranger 3, shaman 4, spiritualist 4, witch 4', '1 standard action', 'touch', '1 living creature touched', NULL, NULL, '8 hours (D)', 'Will (harmless)', 'yes (harmless)', 'While the target of this spell is asleep, she retains some of her normal powers of perception. While she tunes out harmless sounds such as the crackling of the campfire, crickets, or light breezes, she does not take the normal +10 modifier to the DC of Perception checks she attempts while asleep.', 'a handful of crushed glass', NULL, false, false),
  ('vigor', 'Vigor', 'transmutation', NULL, NULL, 0, 'divine', 'adept 0, cleric/oracle 0', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute or until discharged', 'Will negates (harmless)', 'yes', 'This spell infuses the subject with a small surge of strength.', NULL, NULL, false, false),
  ('vile_dog_transformation', 'Vile Dog Transformation', 'transmutation', 'polymorph', 'evil', 3, 'both', 'antipaladin 3, cleric 5, druid 5, shaman 5, sorcerer/wizard 5, witch 5', '10 minutes', 'touch', 'one or more dogs touched', NULL, NULL, '1 hour/level', 'Will negates (see text)', 'no', 'You transform one or more dogs into evil, monstrous creatures.', 'a strip of leather', NULL, false, false),
  ('village_veil', 'Village Veil', 'illusion', 'figment', 'mind-affecting', 5, 'both', 'bard 5, cleric 5, sorcerer/wizard 5, witch 5', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'one 10-ft. cube per level', NULL, '1 day/level', 'Will disbelief', 'no', 'You throw an illusion over an area to make creatures that view or interact with it believe it has suffered some great catastrophe or calamity that renders it utterly worthless for their needs. You must set a few general guidelines when casting the spell as to the nature of this disaster (fire, tornado, bandit raid, plague, etc.), after which the illusion fills in the remaining details to make it seem realistic. When casting the spell, you can grant creatures with particular, clearly identifiable physical traits (race, gender, age category, etc.) immunity to this spell. This allows all such eligible creatures to perceive the true nature of the affected area instead of its illusory appearance. Creatures without this immunity that fail their saving throws always perceive the affected area as having absolutely nothing of interest or worth to them. Unless they have reason for suspicion, they always move on without closely investigating the area. Creatures with sufficient reasons for suspicion who do choose to investigate the area gain another saving throw, this one with a +2 bonus, as they enter the village and directly interact with the illusion.', NULL, NULL, false, false),
  ('vine_strike', 'Vine Strike', 'conjuration', 'creation', NULL, 2, 'both', 'alchemist 2, antipaladin 2, bloodrager 2, druid 2, ranger 2, shaman 2, sorcerer/wizard 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 minute/level (D)', 'Reflex negates (see text)', 'yes', 'Bristles burst from your body, lodging in your opponent and blossoming into entangling vines as you pummel your target. While this spell is in effect, one of your natural attacks or unarmed strikes deals an additional 1d6 points of damage, and each creature hit with that natural weapon or unarmed strike must succeed at a Reflex save or be entangled for the duration of the spell; on a successful Reflex save, the creature is immune to the entangled effect for 1 round. A creature entangled by this spell can spend a standard action to remove the vines, but can be entangled again by further unarmed strikes.', NULL, NULL, false, false),
  ('vinetrap', 'Vinetrap', 'conjuration', 'creation', NULL, 5, 'divine', 'cleric/oracle 5, druid 5', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '1 round/level (D)', 'Reflex negates (see text)', 'yes', 'Vines choked with thorns, blossoms, leaflets, and other floral debris burst to life on and around the subject of this spell, winding around limbs and armor and making it progressively more difficult for the subject to maneuver.', NULL, NULL, true, false),
  ('violent_accident', 'Violent Accident', 'transmutation', NULL, 'curse', 2, 'both', 'cleric 2, mesmerist 2, occultist 2, witch 2', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one creature', NULL, NULL, '1 day or until discharged', 'Reflex half; see text', 'yes', 'You curse the target to suffer a violent accident within the next 24 hours. You have no control over the form the accident takes or when it strikes. The target can avoid being cursed with spell resistance when you cast the spell, but otherwise receives no saving throw. Regardless of the accident’s nature, it is magically empowered to deal an amount of damage equal to 1d8 × your caster level (maximum 5d8 points of damage), and the damage is of a type appropriate to the source of damage (such as fire for an explosion or bludgeoning for a falling object). When the accident occurs, the target can attempt a Reflex saving throw to reduce the damage by half. Although others might be surprised or inconvenienced by the accident, it damages only the target.', NULL, NULL, false, false),
  ('violent_misfire', 'Violent Misfire', 'evocation', NULL, NULL, 3, 'arcane', 'sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one early or advanced firearm', NULL, NULL, '1 round/level', 'Will negates (object)', 'yes (object)', 'This spell creates a chaotic charge within the black powder loaded in a target firearm. The next time the target weapon fires during this spell’s duration, it automatically misfires. If this misfire causes the firearm to explode, the radius of the explosion is doubled and it deals maximum damage to all creatures in the radius. The firearm’s wielder also takes 1d6 additional points of fire damage per 2 caster levels (maximum 10d6) you have.', 'a small piece of flint', NULL, false, false),
  ('viper_bomb_admixture', 'Viper Bomb Admixture', 'conjuration', 'creation', NULL, 4, 'arcane', 'alchemist 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Upon drinking an extract created with this formula, you make a significant change to your magical reserve that modifies the nature of all bombs you create and throw during this extract’s duration. This effect on your magical reserve has no effect on any discoveries that you use to modify your bombs, but you can only have one admixture effect (formula with the word “bomb admixture” in its title) active at a time. If you drink another bomb admixture, the effects of the former bomb admixture end and the new one becomes active.', NULL, NULL, false, false),
  ('virtue', 'Virtue', 'transmutation', NULL, NULL, 0, 'both', 'cleric/oracle 0, druid 0, inquisitor 0, paladin 1, psychic 0, shaman 0', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 min.', 'none', 'yes (harmless)', 'With a touch, you infuse a creature with a tiny surge of life, granting the subject 1 temporary hit point.', NULL, NULL, true, false),
  ('virtuoso_performance', 'Virtuoso Performance', 'transmutation', NULL, NULL, 4, 'arcane', 'bard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'While this spell is active, you may start a second bardic performance while maintaining another. Starting the second performance costs 2 rounds of bardic performance instead of 1. Maintaining both performances costs a total of 3 rounds of bardic performance for each round they are maintained. When this spell ends, one of the performances ends immediately (your choice).', NULL, NULL, false, false),
  ('virulence', 'Virulence', 'necromancy', NULL, 'evil', 4, 'both', 'cleric/oracle 4, warpriest 4, witch 4', '1 standard action', '40 ft.', NULL, 'all living creatures within a 40-ft.-radius burst centered on you', NULL, 'instantaneous', 'see text', 'yes', 'All living creatures within the area of effect, including yourself, must immediately attempt a saving throw with a –2 penalty against any and all diseases they have contracted, even if the onset time has not yet elapsed. On a failed saving throw, the affliction has its usual effect. A successful save does not count toward curing the affliction.', NULL, NULL, false, false),
  ('virulent_miasma', 'Virulent Miasma', 'necromancy', NULL, NULL, 2, 'both', 'antipaladin 2, arcanist 3, bloodrager 3, druid 3, hunter 3, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 round/level', 'Fort negates (see text)', 'see text', 'Virulent miasma creates fog like fog cloud, except that the vapors carry the taint of disease. Living creatures take a –4 penalty on saving throws against disease effects as long as they remain within the cloud and for 1d4+1 rounds after leaving. This effect of the spell allows a Fortitude save to negate it, and it is subject to spell resistance. A creature that succeeds at its saving throw against the fog (or ignores the fog due to spell resistance) is not affected and need not make further saves even if it remains in the fog.', 'a dried scab from a diseased creature', NULL, false, false),
  ('vision', 'Vision', 'divination', NULL, NULL, 7, 'both', 'shaman 7, sorcerer/wizard 7, witch 7; Bloodline dreamspun 7; Elemental School void 7; Mystery ancestor 8, apocalypse 7, ascetic 7, lore 7, occult 7', '1 standard action', 'personal', NULL, NULL, NULL, 'See Text', NULL, NULL, 'This spell functions like legend lore, except that it works more quickly and produces some strain on you. You pose a question about some person, place, or object, then cast the spell. If the person or object is at hand or if you are in the place in question, you receive a vision about it by succeeding on a caster level check (1d20 + 1 per caster level; maximum +25) against DC 20. If only detailed information on the person, place, or object is known, the DC is 25, and the information gained is incomplete. If only rumors are known, the DC is 30, and the information gained is vague. After this spell is complete, you are fatigued.', 'incense worth 250 gp', 'four pieces of ivory worth 50 gp each', false, true),
  ('vision_of_doom', 'Vision of Doom', 'illusion', 'phantasm', 'mind-affecting, evil', 6, 'both', 'cleric/oracle 7, inquisitor 6, shaman 7, witch 7', '10 minutes (see text)', 'unlimited', 'one living creature', NULL, NULL, 'instantaneous', 'Will negates (see text)', 'yes', 'This spell functions exactly as the spell nightmare.', NULL, NULL, false, false),
  ('vision_of_hell', 'Vision of Hell', 'illusion', 'glamer', 'evil, fear', 3, 'both', 'bard 3, bloodrager 3, cleric/oracle 3, mesmerist 3, occultist 3, psychic 3, sorcerer/wizard 3, witch 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '50-ft.-radius emanation', '1 minute/level (D)', 'Will negates', 'no', 'You overlay a realistic illusion of a terrifying hellscape upon an area. Structures, equipment, and creatures within the area are not hidden, though environmental features take on an infernal appearance. While you are prepared for these images and are not affected by them, any other creature within the area must make a Will save or become shaken and also take a –2 penalty on saves versus fear effects; the fear and penalty persists as long as the creature remains in the area. Devils and any lawful evil creatures suffer no negative effects from this spell.', 'a pinch of brimstone', NULL, false, false),
  ('visualization_of_the_body', 'Visualization of The Body', 'transmutation', NULL, 'meditative', 2, 'both', 'cleric 2, druid 2, magus 2, ranger 2, shaman 2, wizard 2', '1 hour', 'personal', 'you', NULL, NULL, '24 hours or until discharged', NULL, NULL, 'You focus your mind on one aspect of your body, aligning the energies within your body to enhance that element. Choose a single physical ability score (Constitution, Dexterity, or Strength).', 'soothing incense worth 200 gp', NULL, false, true),
  ('visualization_of_the_mind', 'Visualization of The Mind', 'transmutation', NULL, 'meditative', 2, 'both', 'cleric 2, shaman 2, wizard 2', '1 hour', 'personal', 'you', NULL, NULL, '24 hours or until discharged', NULL, NULL, 'You enhance a single aspect of your mind, nurturing and empowering it. Choose a single mental ability score (Charisma, Intelligence, or Wisdom). You gain a +5 bonus on ability checks and skill checks associated with that ability score.', 'soothing incense worth 200 gp', NULL, false, true),
  ('vitriolic_mist', 'Vitriolic Mist', 'evocation', NULL, 'acid', 4, 'arcane', 'alchemist 4, bloodrager 4, sorcerer/wizard 4, summoner/unchained summoner 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'This functions as fire shield, except it wreathes you in yellow or green acidic mist instead of hot or cold flames. The spell deals acid damage to attackers and protects you against acid damage. This spell does not shed light.', 'a piece of lemon rind', NULL, false, false),
  ('vocal_alteration', 'Vocal Alteration', 'transmutation', NULL, NULL, 1, 'both', 'alchemist 1, bard 1, inquisitor 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one humanoid creature', NULL, NULL, '1 minute/level', 'Fortitude negates', 'yes', 'You alter the target’s voice to something else. For example, you could make the target’s voice high-pitched, husky, or nasal, or change its accent to an accent you are familiar with. If this spell is used as part of a disguise, the target gets a +10 bonus on the Disguise check when trying to fool a listener.', NULL, NULL, false, false),
  ('volcanic_storm', 'Volcanic Storm', 'evocation', NULL, 'fire', 4, 'both', 'bloodrager 4, druid 4, sorcerer/wizard 4, witch 4; Mystery volcano 4', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, 'cylinder (20-ft. radius, 40 ft. high)', NULL, '1 round/level (D)', 'none', 'yes', 'Chunks of hot volcanic rock and clumps of ash pound down when this spell is cast, dealing 3d6 points of bludgeoning damage and 2d6 points of fire damage to every creature in the area. This damage only occurs once, when the spell is cast. For the remaining duration of the spell, heavy ash rains down in the area. Creatures inside this area take a –4 penalty on Perception skill checks and the entire area is treated as difficult terrain. At the end of the duration, the rock and ash disappear, leaving no aftereffects (other than the damage dealt).', 'obsidian and ash', NULL, true, false),
  ('voluminous_vocabulary', 'Voluminous Vocabulary', 'divination', NULL, NULL, 2, 'both', 'alchemist 3, bard 2, cleric 3, inquisitor 2, medium 2, mesmerist 2, occultist 2, psychic 3, shaman 4, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', 'touch', 'creature touched', NULL, NULL, '8 hours (D)', 'Will negates (harmless)', 'yes (harmless)', 'You choose any language (except for secret languages, such as Druidic). The target gains the ability to speak, understand, read, and write that language. When you cast this spell, you can attempt a DC 15 Linguistics check. If you succeed, choose an additional language, plus one more language for every 10 by which your check result exceeded the DC.', 'a quill', NULL, false, false),
  ('vomit_swarm', 'Vomit Swarm', 'conjuration', 'summoning', NULL, 2, 'arcane', 'alchemist 2, witch 2', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'You vomit forth a swarm of spiders that attacks all other creatures within its area. The swarm begins adjacent to you, but if no living creatures are within its area, it moves in one direction of your choosing at its normal speed.', NULL, NULL, false, false),
  ('vomit_twin', 'Vomit Twin', 'conjuration', 'creation, teleportation', NULL, 3, 'arcane', 'alchemist 3, magus 3, sorcerer/wizard 4, summoner 3', '1 standard action', 'personal', NULL, NULL, NULL, '1 round/level', NULL, NULL, 'Upon casting this spell, you vomit forth a disgusting ooze copy of yourself into a single adjacent square. As long as the twin exists, whenever you take a move action to move, the twin can move as well, although it does not need to follow you and cannot take any other actions. On subsequent rounds, at the start of your turn, you can instantaneously exchange places with your twin, as if using teleport. This is not an action and does not provoke an attack of opportunity.', NULL, NULL, false, false),
  ('vortex', 'Vortex', 'evocation', NULL, 'water', 7, 'both', 'druid 7, shaman 7, sorcerer/wizard 7; Elemental School water 7; Mystery waves 7', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'whirlpool 50 ft. deep, 30 ft. wide at top, and 5 ft. wide at base', '1 round/level (D)', 'Reflex negates, see text', 'yes', 'You create a powerful and immobile whirlpool in any body of liquid large enough to contain the spell’s effect. Any Large or smaller creature that comes in contact with the spell effect must succeed on a Reflex save or take 3d6 points of bludgeoning damage. A Medium or smaller creature that fails its first save must succeed on a second one or be pulled into the whirlpool and held suspended in its powerful currents, taking 1d8 points of damage each round on your turn with no save allowed.', 'a stirring spoon', NULL, true, false),
  ('waft', 'Waft', 'transmutation', NULL, NULL, 5, 'both', 'cleric 5, druid 5, magus 5, occultist 5, shaman 5, sorcerer/wizard 5, spiritualist 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 hour/level', 'Will negates', 'yes', 'You make the targets light enough to be carried by wind.', 'a dandelion seed', NULL, false, false),
  ('wail_of_the_banshee', 'Wail of the Banshee', 'necromancy', NULL, 'death, sonic', 9, 'both', 'shaman 9, sorcerer/wizard 9, witch 9; Domain death 9, repose 9; Bloodline ghoul 9; Mystery bones 9, reaper 9', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one living creature/level within a 40-ft.-radius spread', NULL, NULL, 'instantaneous', 'Fortitude negates', 'yes', 'When you cast this spell, you emit a terrible, soul-chilling scream that possibly kills creatures that hear it (except for yourself). The spell affects up to one creature per caster level, inflicting 10 points of damage per caster level. Creatures closest to the point of origin are affected first.', NULL, NULL, false, false),
  ('wake_of_light', 'Wake of Light', 'evocation', NULL, 'good', 2, 'divine', 'paladin 2', '1 standard action', '120 ft.', NULL, NULL, 'a 10-ft.-wide path in a straight line, up to 120 ft. long', '1 round/level', 'none', 'yes', 'You and your mount lay down a trail of glowing, heavenly mist behind you as you move that makes passage easier for good creatures but more difficult for evil creatures. This glowing trail of mist appears behind your mount in a straight line starting where you cast the spell and ending where your mount ends its movement. The mist takes the form of a path 10 feet wide and up to 120 feet long and always floats just above the ground, up to a height of 1 foot. Thereafter, the mist persists for 1 round per level.', NULL, NULL, true, false),
  ('walk_the_plank', 'Walk the Plank', 'conjuration', 'creation', NULL, 5, 'arcane', 'arcanist 5, sorcerer/wizard 5, summoner 5, summoner (unchained) 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, '20-ft.-by-20-ft. hole, 10 ft. deep/4 levels', '1 round plus 1 round/level', 'Reflex negates (see text)', 'no', 'This spell functions as per create pit, except as noted here. All but the top 10 feet of the hole is filled with saltwater, reducing the fall damage for anyone falling into the pit to 1d3 points of nonlethal damage and allowing Huge or larger creatures at the water’s surface to simply pull themselves out of the pit as part of a normal move action, without a Climb check. Additionally, the pit contains a single advanced shark for every 4 caster levels you have (maximum four advanced sharks). If desired, when you cast the spell, you can substitute two of the summoned sharks for one great white shark. These sharks immediately attack any creature that falls into the pit, even you. If multiple creatures fall in the pit, the sharks attack randomly. When the spell ends, creatures inside the hole rise up with the bottom of the pit, as normal for create pit, but the conjured water and sharks vanish.', 'a shark tooth and a splinter of a ship’s hull', NULL, false, false),
  ('walk_through_space', 'Walk through Space', 'conjuration', 'teleportation', NULL, 6, 'arcane', 'alchemist 6, magus 6, sorcerer/wizard 7, summoner 6, witch 7', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'When under the effects of this spell, you can teleport up to 30 feet as a move action. You must end this movement in an unoccupied space that you can stand on within line of sight. Alternatively, you can spend a move action to teleport to a standing position from lying prone. Teleporting does not provoke attacks of opportunity.', 'a wren’s egg', NULL, false, false),
  ('wall_of_blindness_deafness', 'Wall of Blindness/Deafness', 'necromancy', NULL, NULL, 4, 'both', 'bard 4, cleric 5, sorcerer/wizard 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'translucent wall 20 ft. long/level or a translucent ring with a radius of up to 5 ft./two levels; either form 20 ft. high', 'concentration + 1 round/level', 'Fort negates', 'yes', 'You create a translucent wall of energy, within which can be seen indistinct images of faces with their eyes or ears sewn shut. When you create the wall, decide whether it blinds or deafens. Any creature that passes through the wall must save or become permanently blinded or deafened (as blindness/deafness).', NULL, NULL, false, false),
  ('wall_of_bone', 'Wall of Bone', 'necromancy', NULL, NULL, 4, 'both', 'antipaladin 4, bloodrager 4, cleric 4, psychic 4, sorcerer/wizard 4, spiritualist 4', '1 standard action', 'close (25 ft. + 5 ft./2 level)', NULL, NULL, 'solid wall of humanoid bones with an area of up to one 5-ft. square/level', '1 minute/level', 'none', 'yes; see text', 'This spell creates a vertical wall of skeletal arms that attaches itself to any solid surface. The wall of bone works identically to wall of stone except as noted above and in this spell description. The wall of bone is 1 inch thick per 4 caster levels and composed of up to one 5-foot square per level. The wall created must be vertical, and must rest upon a firm foundation. It cannot be used to bridge a chasm, for instance, or to act as a ramp. Each 5-foot square of the wall has hardness 4 and 7 hit points per inch of thickness. A section of wall whose hit points drops to 0 is breached. If a creature tries to break through the wall with a single attack, the DC of the Strength check is equal to 15 + 2 per inch of thickness.', 'a polished humanoid femur', NULL, false, false),
  ('wall_of_brine_merfolk', 'Wall of Brine (Merfolk)', 'conjuration', 'creation', 'water', 3, 'both', 'druid 4, magus 4, ranger 3, shaman 4, sorcerer/wizard 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall up to 10 ft./level long and 5 ft./level high (S)', 'concentration + 1 round/level', 'none; see text', 'yes', 'You conjure a 5-foot-thick wall of seawater with a powerful current flowing toward one side of the wall, selected by you; a creature attempting to swim against this current must spend 4 squares of movement to enter a square of the wall. A creature that begins its turn in the wall is ejected in the direction of the current just before it acts. The wall provides cover against attacks from out of the water, as usual for a body of water. The water and the currents deflect physical ranged attacks into or through the wall, unless a weapon used is exceptionally massive (such as a siege engine). A creature submerged in the wall takes the usual penalties for underwater combat. The wall blocks gases and liquids and prevents water from mixing at its edges.', 'a bit of coral', NULL, true, false),
  ('wall_of_clockwork', 'Wall of Clockwork', 'conjuration', 'creation', NULL, 5, 'both', 'cleric 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall of bronze clockworks whose area is up to one 5-ft.-square/level (S)', '1 minute/level', 'Reflex half or Reflex negates; see text', 'yes', 'An immobile, vertical wall of spinning cogs and gears springs into existence. Any creature passing through the wall takes 1d6 points of piercing and slashing damage per 2 caster levels (maximum 10d6); a successful Reflex save halves the damage.', NULL, NULL, false, false),
  ('wall_of_ectoplasm', 'Wall of Ectoplasm', 'evocation', NULL, NULL, 5, 'both', 'cleric 5, psychic 5, sorcerer/wizard 5, spiritualist 5; Bloodline ectoplasm 5', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'opaque sheet of ectoplasm up to 10 ft. square/level or a sphere or hemisphere with a radius of up to 1 ft./level', '1 minute/level', 'none, and Will negates; see text', 'yes', 'You draw forth a massive veil of ectoplasm that roils with restless spirits. Immovable once formed, the wall of ectoplasm is 1 inch thick per caster level and covers up to a 10-foot-square area per caster level (so a 10th-level wizard can create a wall of ectoplasm 100 feet long and 10 feet high, a wall 25 feet long and 40 feet high, or any other combination of length and height that does not exceed 1,000 square feet). The plane can be oriented in any fashion and need not be anchored, but must be created continuous and unbroken. The wall can’t include squares that have creatures within them, even if the creatures are on the Ethereal Plane. The wall exists on both the Material Plane and Ethereal Plane, and blocks ethereal and incorporeal creatures from passing through it.', 'small bit of gauze', NULL, false, false),
  ('wall_of_fire', 'Wall of Fire', 'evocation', NULL, 'fire', 3, 'both', 'bloodrager 4, druid 5, magus 4, shaman 4, sorcerer/wizard 4, summoner 3, unchained summoner 4; Domain fire 4; Bloodline efreeti 4; Elemental School fire 4; Mystery battle 4, flame 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'opaque sheet of flame up to 20 ft. long/level or a ring of fire with a radius of up to 5 ft./two levels; either form 20 ft. high', 'concentration + 1 round/level', 'none', 'yes', 'An immobile, blazing curtain of shimmering violet fire springs into existence. One side of the wall, selected by you, sends forth waves of heat, dealing 2d4 points of fire damage to creatures within 10 feet and 1d4 points of fire damage to those past 10 feet but within 20 feet. The wall deals this damage when it appears, and to all creatures in the area on your turn each round. In addition, the wall deals 2d6 points of fire damage + 1 point of fire damage per caster level (maximum +20) to any creature passing through it. The wall deals double damage to undead creatures.', 'a piece of phosphor', NULL, true, false),
  ('wall_of_force', 'Wall of Force', 'evocation', NULL, 'force', 5, 'arcane', 'magus 5, sorcerer/wizard 5; Subdomain isolation 6', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'wall whose area is up to one 10-ft. square/level', '1 round /level (D)', 'none', 'no', 'A wall of force creates an invisible wall of pure force. The wall cannot move and is not easily destroyed. A wall of force is immune to dispel magic, although a mage’s disjunction can still dispel it. A wall of force can be damaged by spells as normal, except for disintegrate, which automatically destroys it. It can be damaged by weapons and supernatural abilities, but a wall of force has hardness 30 and a number of hit points equal to 20 per caster level. Contact with a sphere of annihilation or rod of cancellation instantly destroys a wall of force.', 'powdered quartz', NULL, false, false),
  ('wall_of_ice', 'Wall of Ice', 'evocation', NULL, 'cold', 3, 'arcane', 'bloodrager 4, magus 4, sorcerer/wizard 4, summoner 3, unchained summoner 4; Bloodline boreal 4; Elemental School water 4; Mystery waves 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'anchored plane of ice, up to one 10-ft. square/level, or hemisphere of ice with a radius of up to 3 ft. + 1 ft./level', '1 min./level', 'Reflex negates; see text', 'yes', 'This spell creates an anchored plane of ice or a hemisphere of ice, depending on the version selected. A wall of ice cannot form in an area occupied by physical objects or creatures. Its surface must be smooth and unbroken when created. Any creature adjacent to the wall when it is created may attempt a Reflex save to disrupt the wall as it is being formed. A successful save indicates that the spell automatically fails. Fire can melt a wall of ice, and it deals full damage to the wall (instead of the normal half damage taken by objects). Suddenly melting a wall of ice creates a great cloud of steamy fog that lasts for 10 minutes.', 'a piece of quartz or rock crystal', NULL, false, false),
  ('wall_of_iron', 'Wall of Iron', 'conjuration', 'creation', NULL, 5, 'arcane', 'magus 6, sorcerer/wizard 6, summoner 5, unchained summoner 6; Domain artifice 7; Subdomain metal 6; Elemental School earth 6, metal 6; Mystery metal 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'iron wall whose area is up to one 5-ft. square/level; see text', 'instantaneous', 'see text', 'no', 'You cause a flat, vertical iron wall to spring into being. The wall inserts itself into any surrounding nonliving material if its area is sufficient to do so. The wall cannot be conjured so that it occupies the same space as a creature or another object. It must always be a flat plane, though you can shape its edges to fit the available space.', 'a small iron sheet plus gold dust worth 50 gp', NULL, false, true),
  ('wall_of_lava', 'Wall of Lava', 'conjuration', 'creation', 'earth, fire', 8, 'both', 'druid 8, sorcerer/wizard 8; Elemental School earth 8; Mystery volcano 8', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, NULL, '1 round/level (D)', 'see text', 'no', 'This spell creates a vertical wall of lava that is 1 inch thick for every 4 caster levels and composed of up to one 5-foot square per level. A wall of lava‘s maximum height cannot exceed half of its width (with a minimum height of 5 feet). The wall cannot be conjured so that it occupies the same space as a creature or object. A section of a wall of lava can be destroyed by damage (hardness 4, hp 90), but if a section is destroyed, the remaining lava in the wall immediately fills in any such hole created, reducing the wall’s overall size by one 5-foot square but remaining a contiguous barrier. Each time a weapon strikes a wall of lava, it takes 2d6 points of fire damage (or the creature who strikes the wall takes 2d6 fire damage if the attack was via an unarmed strike or natural attack).', 'a chunk of dried lava', NULL, true, false),
  ('wall_of_light', 'Wall of Light', 'evocation', NULL, 'light', 5, 'both', 'druid 5, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-high vertical sheet of light up to 5 ft. long/level', '1 minute/level (D)', 'Fortitude partial, see text', 'yes', 'An immobile, blinding curtain of white light that blocks line of sight springs into existence.', 'a chip of mica', NULL, true, false),
  ('wall_of_mist', 'Wall of Mist', 'conjuration', 'creation', 'air', 3, 'both', 'magus 3, shaman 3, sorcerer/wizard 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall of thin fog 10 ft. long/level or dense fog 5 ft. long/level; either form 20 ft. high', '1 minute/level', 'none', 'no', 'With a whispered incantation, you conjure a stationary vertical wall of misty vapor. The wall is straight, is 1 foot thick, and has a length up to 10 feet per caster level. The wall obscures vision, granting concealment (20% miss chance) against creatures on the other side of the wall. A creature that shares a square with the wall counts as being on neither side of the wall and neither benefits nor suffers from the concealment.', NULL, NULL, false, false),
  ('wall_of_nausea', 'Wall of Nausea', 'illusion', 'pattern', 'mind-affecting', 3, 'arcane', 'bard 3, psychic 3, sorcerer/wizard 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'transparent wall whose area is up to one 10-ft. square/level', '1 round/level', 'see text', 'no', 'You create a transparent, shimmering wall through which creatures and objects appear to be wildly distorted to viewers. Any creature that passes through the wall is immediately assailed by overwhelming vertigo, becoming nauseated for 1 round unless it succeeds at a Fortitude save; if nauseated, the creature must also succeed at a DC 12 Acrobatics check or fall prone. Creatures gain partial concealment (20% miss chance) against creatures on the other side of the wall.', NULL, NULL, false, false),
  ('wall_of_silver', 'Wall of Silver', 'abjuration', NULL, 'good', 5, 'both', 'bard 5, cleric 6, inquisitor 5, sorcerer/wizard 6', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'transparent wall 20 ft. high by up to 20 ft. long/level', '1 round/level', 'see text', 'yes', 'You create a wall of translucent silver energy that hums and vibrates at the slightest touch.', NULL, NULL, false, false),
  ('wall_of_sound', 'Wall of Sound', 'evocation', NULL, 'sonic', 4, 'arcane', 'bard 4, bloodrager 4, magus 4, sorcerer/wizard 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'translucent wall of sound up to 20 ft. long/level or a ring of sound with a radius of up to 5 ft./two levels; either form 20 ft. high', 'concentration + 1 round/level', 'none', 'yes', 'A translucent barrier of pure sound springs into existence. This wall is silent except for a faint hum, but bursts with discordant noise when touched by an object or creature. The wall deflects arrows, bolts, loose debris, and Small or smaller flying creatures like a wind wall spell, except these things rebound harmlessly rather than being directed upward. The burst of discordant noise deals 2d4 points of sonic damage to creatures within 10 feet of the triggering object or creature; touching or passing through the wall deals 2d6 points of sonic damage + 1 point of sonic damage per caster level (maximum +20). If you evoke the wall so that it appears where creatures are, each creature takes damage as if passing through the wall. A silence spell suppresses the wall within its area, but the wall reappears when the silence ends.', 'a tuning fork and a quartz crystal', NULL, false, false),
  ('wall_of_split_illumination', 'Wall of Split Illumination', 'evocation', NULL, 'darkness, light', 3, 'both', 'bard 3, cleric 3, sorcerer/ wizard 3, inquisitor 3, magus 3, occultist 3, shaman 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, '10-ft.-high vertical sheet of illumination up to 5 ft. long/level', '1 minute/level (D)', 'none', 'no', 'An immobile curtain of illumination springs into existence. When created, one side of the wall (designated by you) radiates bright light to a range of 60 feet away from that side while the other side radiates darkness to an equal distance. This effect alters the illumination level by up to two steps toward either bright light (the light side) or darkness (the dark side). The wall also obstructs vision through it, regardless of which side of the wall the viewer is on.', NULL, NULL, false, false),
  ('wall_of_stone', 'Wall of Stone', 'conjuration', 'creation', 'earth', 4, 'both', 'cleric/oracle 5, druid 6, magus 5, shaman 6, sorcerer/wizard 5, summoner 4, unchained summoner 5; Domain earth 5; Elemental School earth 5; Mystery stone 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'stone wall whose area is up to one 5-ft. square/level (S)', 'instantaneous', 'see text', 'no', 'This spell creates a wall of rock that merges into adjoining rock surfaces. A wall of stone is 1 inch thick per four caster levels and composed of up to one 5-foot square per level. You can double the wall’s area by halving its thickness. The wall cannot be conjured so that it occupies the same space as a creature or another object.', 'a small block of granite', NULL, true, false),
  ('wall_of_suppression', 'Wall of Suppression', 'abjuration', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Mystery succor 9', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'anti-magic wall occupying up to two 5 ft. cubes/level (S)', '10 minutes/level; see text', 'none', 'no', 'You create a wall of glittering motes that suppresses or even negates any magical effect passing through it. The wall appears to have no actual substance and does not physically obstruct or impede anything attempting to move through it. However, the wall exerts a powerful anti-magical effect. Any magic item or magical spell or effect of your caster level or lower that passes through the wall is suppressed for 1 round per level.', 'powdered adamantine worth 1,000 gp', NULL, false, true),
  ('wall_of_thorns', 'Wall of Thorns', 'conjuration', 'creation', NULL, 5, 'divine', 'druid 5, shaman 5; Domain plant 5; Subdomain blood 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall of thorny brush, up to one 10-ft. cube/level (S)', '10 min./level (D)', 'none', 'no', 'A wall of thorns spell creates a barrier of very tough, pliable, tangled brush bearing needle-sharp thorns as long as a human’s finger. Any creature forced into or attempting to move through a wall of thorns takes piercing damage per round of movement equal to 25 minus the creature’s AC. Dexterity and dodge bonuses to AC do not count for this calculation. (Creatures with an AC of 25 or higher, without considering Dexterity and dodge bonuses, take no damage from contact with the wall.)', NULL, NULL, false, false),
  ('wandering_star_motes', 'Wandering Star Motes', 'illusion', 'pattern', 'light, mind-affecting', 4, 'both', 'bard 4, shaman 4, sorcerer/wizard 4, witch 4; Bloodline astral 4; Elemental School void 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1/round per level', 'Will negates; see text', 'yes', 'You create sparkling motes of bright light that shoot toward the target and swirl around it in a complex pattern. The pattern clearly outlines the target and radiates light as if it were a sunrod, negating any concealment for the target. The target must make a successful Will save. If the target fails its save, it is dazed for 1 round and must make another save on its next turn or be dazed again for 1 round. The target must continue making Will saves each round. If a target makes its Will save, the wandering star motes jump to the nearest enemy within 30 feet, who must now make Will saves every round or be dazed. Any time a target makes its Will save, the wandering star motes jump to the next nearest enemy within 30 feet.', 'a sprinkle of flash powder', NULL, false, false),
  ('wandering_trail', 'Wandering Trail', 'transmutation', NULL, NULL, 6, 'divine', 'druid 6', '1 standard action', '1 mile/level', 'up to one creature/level within 180 feet', NULL, NULL, '1 day/level (D)', 'none', 'no', 'You cause the trail left by the targets within range to automatically reroute, potentially taking any course within the area. Your modification of the trail within the spell’s area can result in a trail at least half the original length or up to twice the original length. If the trail continues beyond the spell’s range, you must leave it connecting at that point on the edge of the spell’s range. If a tracking creature exceeds the DC of the skill check to follow the trail by an amount equal to your caster level, the tracker recognizes that the trail has been manipulated by this spell, although it cannot see the trail’s true nature unless it uses magical means, such as true seeing.', NULL, NULL, false, false),
  ('wandering_weather', 'Wandering Weather', 'transmutation', NULL, NULL, 8, 'both', 'cleric 8, druid 8, shaman 8, sorcerer/wizard 8, witch 8', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as control weather except you can opt for the weather to remain centered on you as you move.', NULL, NULL, false, false),
  ('ward_of_the_season', 'Ward of the Season', 'abjuration', NULL, NULL, 3, 'both', 'cleric 4, druid 3, ranger 3, shaman 3, witch 3', '1 standard action', 'touch', 'one creature', NULL, NULL, '1 hour/level', 'Will negates (harmless)', 'no', 'This spell harnesses the power of the seasons to protect the target and grant a number of bonuses. This spell has one of four different effects. The caster of the spell can select any one of the following four effects, but can change the effect as a standard action that reduces the total remaining duration by 1 hour.', NULL, NULL, false, false),
  ('ward_shield', 'Ward Shield', 'abjuration', NULL, NULL, 4, 'both', 'cleric 4, inquisitor 4, magus 4, sorcerer/wizard 4', NULL, 'touch', 'shield touched', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'With a touch, you enchant a shield and enable it to protect its wielder from hostile spells.', NULL, NULL, false, false),
  ('ward_the_faithful', 'Ward the Faithful', 'abjuration', NULL, NULL, 3, 'divine', 'inquisitor 3', '1 standard action', 'touch', NULL, '10-ft.-radius emanation from touched creature', NULL, '10 minutes/level', 'Will negates (harmless)', 'no', 'All creatures within the area who worship the same god as you gain a +2 deflection bonus to AC and a +2 resistance bonus on all saves. At 12th level, these bonuses increase to +3. At 18th level, the bonuses increase to +4.', NULL, NULL, true, false),
  ('warding_weapon', 'Warding Weapon', 'abjuration', NULL, NULL, 1, 'arcane', 'bloodrager 1, magus 1, occultist 1, psychic 2, sorcerer/wizard 2, summoner/unchained summoner 2', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'The focus of this spell flies upward above your head and takes a defensive position within your space. It lunges at opponents, as if guided by a martially trained hand, parrying and turning back melee attacks aimed at you, but does not strike back at any opponent nor does it damage them. The weapon serves only as a defense. While it protects you, you can cast spells without provoking attacks of opportunity, without the need to cast them defensively. A creature with the Disruptive feat can easily bypass this spell’s defenses. You provoke attacks of opportunity for casting spells against these creatures even when subject to this spell, though you can still choose to cast defensively.', NULL, 'one melee weapon you are proficient in and you are holding', false, false),
  ('warp_metal', 'Warp Metal', 'transmutation', NULL, 'earth', 4, 'both', 'bloodrager 4, cleric 4, druid 4, medium 4, occultist 4, psychic 4, sorcerer/wizard 4', '1 standard action', 'close (25 ft. plus 5 ft./2 levels)', NULL, NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You cause metal to bend and warp, permanently destroying its straightness, form, and strength. A warped door springs open (or becomes stuck, requiring a successful Strength check to open, at your option). A vehicle grinds to a halt and ceases to operate. Warped ranged weapons are useless. A warped melee weapon imposes a –4 penalty on attack rolls.', 'a twisted wire', NULL, false, false),
  ('warp_wood', 'Warp Wood', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, shaman 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 Small wooden object/level, all within a 20-ft. radius', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'You cause wood to bend and warp, permanently destroying its straightness, form, and strength. A warped door springs open (or becomes stuck, requiring a Strength check to open, at your option). A boat or ship springs a leak. Warped ranged weapons are useless. A warped melee weapon causes a -4 penalty on attack rolls.', NULL, NULL, false, false),
  ('wartrain_mount', 'Wartrain Mount', 'enchantment', 'compulsion', 'mind-affecting', 1, 'both', 'antipaladin 1, bard 2, druid 2, inquisitor 1, paladin 1, ranger 1', '1 minute', 'close (25 ft. + 5 ft./2 levels)', 'one indifferent or friendly animal', NULL, NULL, '1 hour/level', 'none', 'yes', 'You instill the target animal with the combat training general purpose (see Handle Animal). This supersedes the animal’s previous trained purpose and any tricks it knows. When the spell ends, it reverts to its previous trained purpose and known tricks.', 'a swatch of black cloth', NULL, false, false),
  ('watchful_animal', 'Watchful Animal', 'divination', 'scrying', NULL, 4, 'both', 'druid 4, ranger 4, shaman 4, sorcerer/wizard 4, witch 4', '10 minutes', 'medium (100 ft. plus 10 ft./level)', NULL, NULL, 'magical sensor', '10 minutes/level', 'none', 'no', 'You place a scrying sensor on your animal companion or familiar.', 'a desiccated fly', NULL, true, false),
  ('watchful_eye', 'Watchful Eye', 'abjuration', NULL, NULL, 1, 'divine', 'cleric/oracle 1, paladin 1 (Folgrit)', '1 standard action', NULL, NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'This spell emulates Folgrit’s motherly protection. It functions as shield other, except as noted above, and you must maintain line of effect to the target.', NULL, 'a pair of silver or gold rings worth 10 gp, worn by both you and the target', false, true),
  ('water_breathing', 'Water Breathing', 'transmutation', NULL, NULL, 3, 'both', 'alchemist 3, bloodrager 3, cleric/oracle 3, druid 3, magus 3, psychic 3, shaman 3, sorcerer/wizard 3, summoner/unchained summoner 3; Domain water 3; Elemental School water 3; Mystery waves 3', '1 standard action', 'touch', 'living creatures touched', NULL, NULL, '2 hours/level; see text', 'Will negates (harmless)', 'yes (harmless)', 'The transmuted creatures can breathe water freely. Divide the duration evenly among all the creatures you touch. The spell does not make creatures unable to breathe air.', 'short reed or piece of straw', NULL, true, false),
  ('water_of_maddening', 'Water of Maddening', 'conjuration', 'creation', NULL, 2, 'both', 'alchemist 2, antipaladin 2, cleric 3, druid 3, witch 3', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'up to 1 flask per 2 levels', 'instantaneous', 'Fortitude partial', 'no', 'This spell generates what appears to be clear, pure water, but it is in fact a foul secretion known as water of maddening. The liquid functions in all the same ways as unholy water (see curse water).', '250 gp of powdered amber', NULL, false, true),
  ('water_shield', 'Water Shield', 'evocation', NULL, 'acid, water', 3, 'both', 'cleric/oracle 4, druid 3, sorcerer/wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level (D)', NULL, NULL, 'This spell surrounds you in a spout of clear acid that aids in defecting attacks and damages creatures that attack you in melee. The constantly upward-rushing waters grant you a measure of protecting, shielding you so you only take half damage from acid and fire-based attacks. If such an attack allows a Reflex save for half damage, you take no damage on a successful save.', '1 cup of water', NULL, true, false),
  ('water_walk', 'Water Walk', 'transmutation', NULL, 'water', 2, 'both', 'cleric/oracle 3, medium 2, psychic 3, ranger 3, shaman 3, witch 3; Subdomain oceans 3', '1 standard action', 'touch', NULL, NULL, NULL, '10 min./level (D)', 'Will negates (harmless)', 'yes (harmless)', 'The transmuted creatures can tread on any liquid as if it were firm ground. Mud, oil, snow, quicksand, running water, ice, and even lava can be traversed easily, since the subjects’ feet hover an inch or two above the surface. Creatures crossing molten lava still take damage from the heat because they are near it. The subjects can walk, run, charge, or otherwise move across the surface as if it were normal ground.', NULL, NULL, true, false),
  ('waterproof', 'Waterproof', 'abjuration', NULL, 'water', 1, 'both', 'alchemist 1, bard 1, bloodrager 1, cleric 1, druid 1, magus 1, ranger 1, shaman 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'one touched creature, or one touched object of up to 10 lbs/level', NULL, NULL, '24 hours', 'Will negates (harmless)', 'yes (harmless)', 'This spell renders a touched object waterproof for the duration of the spell. The object must be no larger than 10 pounds per caster level. The spell protects the object from any mundane liquids (such as alcohol or oil) but not from magically created liquids.', NULL, NULL, false, false),
  ('wave_form', 'Wave Form', 'transmutation', NULL, 'water', 4, 'both', 'arcanist 4, bloodrager 4, cleric 4, druid 4, hunter 4, oracle 4, shaman 4, sorcerer 4, warpriest 4, wizard 4', '1 standard action', 'personal', 'you', NULL, NULL, 'instantaneous', 'see text', NULL, 'You transform into a wave of frothing water up to 15 feet wide and 15 feet tall, as space permits, and then surge forth in a straight line in the direction of your choice, moving up to twice your base movement speed before immediately returning to your normal form. This movement does not provoke attacks of opportunity. While in wave form, you are immune to weapon attacks and attacks that target a specific number of creatures (since the spell is instantaneous, this is mainly relevant for readied actions and the like). All creatures and unattended objects in your path take 4d6 points of bludgeoning damage and are knocked prone. A successful Reflex save prevents a creature from being knocked prone.', NULL, NULL, false, false),
  ('wave_shield', 'Wave Shield', 'abjuration', NULL, 'water', 1, 'both', 'bloodrager 1, druid 1, magus 1, shaman 1, sorcerer/wizard 1, witch 1', '1 immediate action', 'personal', 'you', NULL, NULL, '1 round or until discharged', NULL, NULL, 'You create a rushing torrent of water in the rough outline of a shield. The water protects you from one physical or fire attack, granting you DR/— and fire resistance equal to half your caster level (minimum 1) on that attack. Once the spell has reduced the damage of one attack against you, it is discharged.', NULL, NULL, false, false),
  ('waves_of_blood', 'Waves of Blood', 'conjuration', 'creation', NULL, 3, 'arcane', 'bloodrager 3, magus 3, psychic 3, sorcerer/wizard 3, spiritualist 3, witch 3', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous and 1 round; see text', 'Reflex negates, Fort negates (see text)', 'no', 'You cause torrents of roiling blood to push your opponents away from you. This wave attempts a bull rush combat maneuver against all creatures within its area of effect, and you bull rush creatures of any size in this way. Attempt a single combat maneuver check and apply the result to each creature within the area. Your CMB for this bull rush is equal to your caster level plus your Intelligence, Wisdom, or Charisma modifier, whichever is highest. This bull rush doesn’t provoke attacks of opportunity. Any creature in the area must also succeed at a Fortitude saving throw or become sickened for 1d6 rounds by the tide of blood.', 'a drop of the caster’s blood', NULL, false, false),
  ('waves_of_ecstasy', 'Waves of Ecstasy', 'enchantment', 'compulsion', 'emotion, mind-affecting', 6, 'both', 'bard 6, cleric/oracle 7, sorcerer/wizard 7, witch 7', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, '1 round/level; see text', 'Will partial (see text)', 'yes', 'You emanate waves of intense pleasure that cause all targets within range to falter. Affected creatures are stunned for 1 round and are staggered for the remainder of the spell. A creature that makes its save is staggered for the first round and can act normally thereafter.', NULL, NULL, false, false),
  ('waves_of_exhaustion', 'Waves of Exhaustion', 'necromancy', NULL, NULL, 7, 'arcane', 'sorcerer/wizard 7, witch 7; Domain repose 8; Subdomain toil 7; Bloodline daemon 7', '1 standard action', '60 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'no', 'yes', 'Waves of negative energy cause all living creatures in the spell’s area to become exhausted. This spell has no effect on a creature that is already exhausted.', NULL, NULL, false, false),
  ('waves_of_fatigue', 'Waves of Fatigue', 'necromancy', NULL, NULL, 5, 'arcane', 'sorcerer/wizard 5, witch 5; Subdomain  toil 5', '1 standard action', '30 ft.', NULL, 'cone-shaped burst', NULL, 'instantaneous', 'no', 'yes', 'Waves of negative energy render all living creatures in the spell’s area fatigued. This spell has no effect on a creature that is already fatigued.', NULL, NULL, false, false),
  ('weaken_powder', 'Weaken Powder', 'transmutation', NULL, NULL, 1, 'both', 'druid 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', '1 loaded firearm', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'Ammunition in the target firearm generates less of an explosive charge when fired. With such ammunition, the firearm’s range increment is halved and the firer takes a –2 penalty on damage rolls. If aware of this spell’s effect prior to firing the altered ammunition (a DC 16 Spellcraft check to identify the spell being cast or similar effect), the firearm’s user can spend a standard action to clear the altered ammunition from the firearm. Doing so destroys that ammunition.', 'an empty paper cartridge', NULL, true, false),
  ('weapon_of_awe', 'Weapon of Awe', 'transmutation', NULL, 'emotion', 2, 'divine', 'cleric/oracle 2, inquisitor 2, paladin 2', '1 standard action', 'touch', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'You transform a single weapon into an awe-inspiring instrument. The weapon gains a +2 sacred bonus on damage rolls, and if the weapon scores a critical hit, the target of that critical hit becomes shaken for 1 round with no Saving Throw.', NULL, NULL, true, false),
  ('weapons_against_evil', 'Weapons Against Evil', 'transmutation', NULL, NULL, 1, 'divine', 'cleric/oracle 1, inquisitor 1, paladin 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, NULL, '1 round/level', 'Fort negates (harmless, object)', 'yes (harmless, object)', 'Each weapon this spell affects each shines with pale light that dimly illuminates a 5-foot square. These weapons also ignore the DR of evil creatures that have DR 5 or lower, as long as the damage reduction is not DR/epic.', NULL, NULL, true, false),
  ('weaponwand', 'Weaponwand', 'transmutation', NULL, NULL, 1, 'both', 'bard 1, cleric 1, inquisitor 1, magus 1', '1 round', 'touch', 'one weapon', NULL, NULL, '1 minute/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'When you cast this spell on a weapon, you cause a portion of the weapon to open like the skin of a partially peeled apple, revealing a space large enough to insert a single wand within. As part of the spell’s casting, you can insert a single wand into the weapon, at which point the weapon returns to its original form with the wand held inside of it without negatively impacting the weapon’s integrity. For the spell’s duration, a character who wields the transmuted weapon is also considered to be wielding the wand as well. You can attack normally with the weapon or use the weapon as if it were the encased wand. If the effect created by the wand requires an attack roll to successfully strike a foe, you may make the attack roll as if you were making an attack with the weapon at its highest bonus (including any bonuses the weapon would normally receive) rather than just a normal attack with the wand—doing so does not allow you to add the weapon’s damage to the wand’s attack roll, but instead allows you to use your skill with the weapon to boost your chance of hitting with the spell.', NULL, 'a magic wand', false, false),
  ('web', 'Web', 'conjuration', 'creation', NULL, 2, 'arcane', 'magus 2, sorcerer/wizard 2, witch 2; Elemental School wood 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'webs in a 20-ft.-radius spread', '10 min./level (D)', 'Reflex negates; see text', 'no', 'Web creates a many-layered mass of strong, sticky strands. These strands trap those caught in them. The strands are similar to spiderwebs but far larger and tougher. These masses must be anchored to two or more solid and diametrically opposed points or else the web collapses upon itself and disappears. Creatures caught within a web become grappled by the sticky fibers. Attacking a creature in a web doesn’t cause you to become grappled.', 'spider web', NULL, false, false),
  ('web_bolt', 'Web Bolt', 'conjuration', 'creation', NULL, 1, 'arcane', 'bloodrager 1, magus 1, sorcerer/wizard 1, witch 1', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, NULL, 'fist-sized blob of webbing', '1 min./level', 'Reflex negates; see text', 'no', 'You launch a ball of webbing at a target, which must make a save or be affected as if by a web spell occupying only the creature’s space. If the creature saves or breaks free of the webbing, the remaining webs dissolve and the square is not considered difficult terrain. The spell has no effect if the target is not on or adjacent to a solid surface that can support the webbing.', NULL, NULL, false, false),
  ('web_cloud', 'Web Cloud', 'conjuration', 'creation', NULL, 4, 'arcane', 'sorcerer/wizard 4, witch 4', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'cloud spreads in 20-ft. radius, 20 ft. high', '1 minute/level', 'Reflex partial; see text', 'no', 'You create a cloud of flame-resistant strands of adhesive webbing that billows and flows much like a cloudkill spell. The cloud moves away from you at a rate of 10 feet per round, rolling along the surface of the ground.', NULL, NULL, false, false),
  ('web_shelter', 'Web Shelter', 'conjuration', 'creation', NULL, 2, 'both', 'cleric/oracle 2, druid 2, ranger 2, shaman 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2', '1 minute', 'close (25 ft. + 5 ft./two levels)', NULL, NULL, '5 ft.–10 ft. diameter web sphere or 5 ft.–20 ft. hemisphere', '1 hour/level (D)', 'none', 'no', 'You create a shelter of slightly sticky webbing. The shelter has a hinged door large enough to accommodate a Medium creature. The opaque walls of the shelter measure 1 inch thick and provide total cover to anyone within it.', NULL, NULL, true, false),
  ('weird', 'Weird', 'illusion', 'phantasm', 'emotion, fear, mind-affecting', 9, 'arcane', 'sorcerer/wizard 9; Domain madness 9; Bloodline harrow 9', '1 standard action', NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like phantasmal killer, except it can affect more than one creature. Only the affected creatures see the phantasmal creatures attacking them, though you see the attackers as shadowy shapes.', NULL, NULL, false, false),
  ('what_grows_within', 'What Grows Within', 'necromancy', NULL, 'evil', 6, 'both', 'arcanist 6, bard 6, cleric/oracle 6, druid 6, hunter 6, mesmerist 6, psychic 6, skald 6, sorcerer/wizard 6, warpriest 6, witch 6', '1 swift action', 'personal', NULL, NULL, 'you', '1 round/level', 'see text', 'no', 'You infuse yourself with the essence of the Inmost Blot and gain a +3 profane bonus on Will saving throws for the spell’s duration. When you prepare what grows within for the first time, or the first time you use it via a spell-completion or spell-trigger item, you can thereafter be targeted by the infected dreams ability. As long as you are under the effects of what grows within, your mind-affecting spells carry this supernatural taint within them and can infect those who succumb to those effects. Whenever you successfully affect a creature with one of your mind-affecting spells (this requires the target to fail its saving throw against the spell if the spell allows a save, but automatically affects a target if the spell does not allow a saving throw), that target must also succeed at a Fortitude saving throw against what grows within or it immediately becomes afflicted by a lesser version of seeded infestation. This infestation does not expose the victim to infectious dreams, but it can ultimately result in that creature’s transformation into one of the seeded. Each time you affect a creature with what grows within in this manner, the remaining duration of what grows within is reduced by 1 round. If you affect multiple creatures in a round, you choose the order in which they must save against the effects of what grows within, and reduce the spell’s remaining duration by 1 round each time one of them is affected by the infestation.', NULL, NULL, false, false),
  ('whip_of_ants', 'Whip of Ants', 'conjuration', 'summoning', NULL, 6, 'both', 'bard 6, druid 6, sorcerer/wizard 6, summoner/unchained summoner 6, witch 6', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as whip of spiders, except it summons army ants, and any creature you strike with the whip takes swarm damage as if it were attacked by an army ant swarm (3d6 points of damage plus poison and distraction). If you transform the whip into an army ant swarm, it has 16 hit points.', NULL, NULL, false, false),
  ('whip_of_centipedes', 'Whip of Centipedes', 'conjuration', 'summoning', NULL, 5, 'both', 'bard 5, druid 5, sorcerer/wizard 5, summoner/unchained summoner 5, witch 5', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions as whip of spiders, except it summons centipedes, and any creature you strike with the whip takes swarm damage as if it were attacked by a centipede swarm (2d6 points of damage plus poison and distraction). If you transform the whip into a centipede swarm, it has 10 hit points.', NULL, NULL, false, false),
  ('whip_of_spiders', 'Whip of Spiders', 'conjuration', 'summoning', NULL, 2, 'both', 'bard 2, druid 2, sorcerer/wizard 2, summoner/unchained summoner 2, witch 2', '1 standard action', '0 ft.', NULL, NULL, 'whiplike swarm', '1 round/level (D (see text)', 'none', 'yes', 'You summon hundreds of Diminutive spiders, which cling together in the form of a whip made for a creature of your size. You can wield this object as if it were an actual whip, except you make a melee touch attack with it instead of a regular attack. Any creature you strike with the whip takes swarm damage as if it were attacked by a spider swarm (1d6 points of damage plus poison and distraction). The swarm whip is able to damage creatures with armor or natural armor, even if a normal whip could not. It cannot be used to make bull rush, grapple, or trip attacks, and (unlike a swarm) is subject to a miss chance for concealment and cover.', 'a square of red cloth', NULL, true, false),
  ('whirlwind', 'Whirlwind', 'evocation', NULL, 'air', 8, 'divine', 'druid 8, shaman 8; Domain air 8, weather 8; Elemental School void 8; Mystery wind 8', '1 standard action', 'long (400 ft. + 40 ft./level)', NULL, NULL, 'cyclone 10 ft. wide at base, 30 ft. wide at top, and 30 ft. tall', '1 round/level (D)', 'Reflex negates; see text', 'yes', 'This spell creates a powerful cyclone of raging wind that moves through the air, along the ground, or over water at a speed of 60 feet per round. You can concentrate on controlling the cyclone’s every movement or specify a simple program. Directing the cyclone’s movement or changing its programmed movement is a standard action for you. The cyclone always moves during your turn. If the cyclone exceeds the spell’s range, it moves in a random, uncontrolled fashion for 1d3 rounds and then dissipates. (You can’t regain control of the cyclone, even if it comes back within range.)', NULL, NULL, true, false),
  ('whispering_lore', 'Whispering Lore', 'divination', NULL, NULL, 1, 'both', 'cleric 2, druid 1, psychic 1, ranger 1, witch 1', '1 full-round action', 'personal', 'you', NULL, NULL, '10 minutes/level (D)', NULL, NULL, 'Upon casting this spell, you are able to gain knowledge from the land itself. As you walk through the terrain, it whispers information in a language you understand, though the whispering is so rambling it is hard to distinguish useful information. This whispering grants you a +4 insight bonus on a single Knowledge skill type appropriate to the type of terrain you are in. If you are within a cold, desert, forest, jungle, mountain, plains, swamp, or water environment, you gain the bonus on Knowledge (nature) checks. If you are within an underground environment, you gain the bonus on Knowledge (dungeoneering) checks. If you are within an urban environment, you gain the bonus on Knowledge (local) checks. If you are on a plane other than the Material Plane, you gain the bonus on Knowledge (planes) checks. If you enter a new terrain, you lose the previous terrain’s skill bonus and gain the new bonus.', 'an owl’s beak', NULL, true, false),
  ('whispering_wind', 'Whispering Wind', 'transmutation', NULL, 'air', 2, 'both', 'bard 2, inquisitor 2, medium 2, mesmerist 2, psychic 2, sorcerer/wizard 2; Subdomain wind 1; Elemental School air 2, wood 2', '1 standard action', '1 mile/level', NULL, '10-ft.-radius spread', NULL, 'no more than 1 hour/level or until discharged (destination is reached)', 'none', 'no', 'You send a message or sound on the wind to a designated spot. The whispering wind travels to a specific location within range that is familiar to you, provided that it can find a way to the location. A whispering wind is as gentle and unnoticed as a zephyr until it reaches the location. It then delivers its whisper-quiet message or other sound. Note that the message is delivered regardless of whether anyone is present to hear it. The wind then dissipates.', NULL, NULL, false, false),
  ('wicker_horse', 'Wicker Horse', 'conjuration', 'creation', NULL, 2, 'both', 'occultist 2, shaman 2, summoner 2, summoner (unchained) 2, witch 2', '10 minutes; see text', 'touch', NULL, NULL, 'a horselike wicker construct', '1 hour/level (D)', 'none', 'no', 'Reeds, grasses, creepers, or thin tree branches (your choice) that you touch animate, twisting and bending to form a wicker horse complete with a riding saddle. The object is animated, but retains a wickerlike appearance.', 'a reed or twig', NULL, true, false),
  ('widen_auras', 'Widen Auras', 'transmutation', NULL, NULL, 2, 'divine', 'antipaladin 2, paladin 2 Casting Time 1 standard action Components V', NULL, 'personal', 'you', NULL, NULL, '1 minute/level (D)', NULL, NULL, 'The range of your antipaladin or paladin auras doubles. For example, if you’re a paladin, your aura of courage affects allies within 20 feet instead of within 10 feet.', NULL, NULL, false, false),
  ('wild_instinct', 'Wild Instinct', 'divination', NULL, NULL, 2, 'both', 'bloodrager 2, druid 2, ranger 2, shaman 2', 'standard action', 'personal', 'you', NULL, NULL, '8 hours', NULL, NULL, 'This spell sharpens your senses, allowing you to perceive threats you would otherwise miss.', NULL, NULL, true, false),
  ('wilderness_soldiers', 'Wilderness Soldiers', 'transmutation: Level druid 2, ranger 2', NULL, NULL, 9, 'arcane', NULL, '1 standard action', '30 ft.', NULL, '30-ft.-radius emanation, centered on you', NULL, '1 round/level', 'none', 'no', 'You call on the plants nearby to aid you in combat. This spell is ineffective if no plants you can direct are within the area. You can spend a swift action and/or a standard action on each of your turns to direct one of the following attacks. The attack bonus or CMB for these attacks equals your base attack bonus + your Wisdom modifier. You grant a +1 bonus per three caster levels (maximum +5) on damage rolls due to this spell. Your wilderness soldiers never provoke attacks of opportunity, and they do not count as allies for flanking or other purposes.', NULL, NULL, false, false),
  ('wind_blades', 'Wind Blades', 'transmutation', NULL, 'air', 5, 'both', 'druid 5, magus 5, sorcerer/wizard 5, witch 5', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 round/level', 'Will negates', 'yes', 'You harden the air around the target into jagged invisible blades that deal damage based on how fast the target moves. On its turn, the target takes 1d6 points of slashing damage if it moves at least 5 feet, plus 1d6 points of slashing damage for each additional 10 feet of movement. Movement that doesn’t pass through air (such as burrowing, swimming, or teleportation) doesn’t cause this damage. In areas of strong wind, the target takes damage on its turn, even if it doesn’t move. The wind deals 1d8 points of slashing damage for strong wind, plus 1d8 for every wind category above strong. This extra damage does not occur from instantaneous wind effects (such as gust of wind), only from wind effects that last at least 1 round.', NULL, NULL, false, false),
  ('wind_walk', 'Wind Walk', 'transmutation', NULL, 'air', 6, 'both', 'alchemist 6, cleric/oracle 6, druid 7, shaman 7; Subdomain wind 6', '1 standard action', 'touch', NULL, NULL, NULL, '1 hour/level (D); see text', 'no and Will negates (harmless)', 'no and yes (harmless)', 'You alter the substance of your body to a cloud-like vapor (as the gaseous form spell) and move through the air, possibly at great speed. You can take other creatures with you, each of which acts independently.', NULL, NULL, true, false),
  ('wind_wall', 'Wind Wall', 'evocation', NULL, 'air', 2, 'both', 'bloodrager 3, cleric/oracle 3, druid 3, magus 3, ranger 2, shaman 3, sorcerer/wizard 3, summoner 2, unchained summoner 3; Domain air 2; Elemental School air 3, wood 3', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'wall up to 10 ft./level long and 5 ft./level high (S)', '1 round/level', 'none; see text', 'yes', 'An invisible vertical curtain of wind appears. It is 2 feet thick and of considerable strength. It is a roaring blast sufficient to blow away any bird smaller than an eagle, or tear papers and similar materials from unsuspecting hands. (A Reflex save allows a creature to maintain its grasp on an object.) Tiny and Small flying creatures cannot pass through the barrier. Loose materials and cloth garments fly upward when caught in a wind wall. Arrows and bolts are deflected upward and miss, while any other normal ranged weapon passing through the wall has a 30% miss chance. (A giant-thrown boulder, a siege engine projectile, and other massive ranged weapons are not affected.) Gases, most gaseous breath weapons, and creatures in gaseous form cannot pass through the wall (although it is no barrier to incorporeal creatures).', 'a tiny fan and an exotic feather', NULL, true, false),
  ('winds_of_vengeance', 'Winds of Vengeance', 'evocation', NULL, 'air', 9, 'both', 'cleric/oracle 9, druid 9, shaman 9, sorcerer/wizard 9; Subdomain wind 9; Elemental School air 9, wood 9; Mystery wind 9', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute/level', NULL, NULL, 'You surround yourself with a buffeting shroud of supernatural, tornado-force winds. These winds grant you a fly speed of 60 feet with perfect maneuverability. Neither your armor nor your load affects this fly speed. The winds shield you from any other wind effects, and form a shell of breathable air around you, allowing you to fly and breathe underwater or in outer space.', NULL, NULL, true, false),
  ('windy_escape', 'Windy Escape', 'transmutation', NULL, 'air', 1, 'both', 'bard 1, bloodrager 1, druid 1, magus 1, sorcerer/wizard 1 (sylph)', '1 immediate action', 'personal', 'you', NULL, NULL, 'instantaneous', NULL, NULL, 'You respond to an attack by briefly becoming vaporous and insubstantial, allowing the attack to pass harmlessly through you.', NULL, NULL, false, false),
  ('wing_bounty', 'Wing Bounty', 'conjuration', 'creation', NULL, 2, 'divine', 'druid 2, shaman 2', '1 standard action', '0 ft.', NULL, NULL, '2d4 berries + 2 berries/level', '1 day/level', 'none', 'no', 'Your wings sprout a variety of colorful and flavorful berries.', NULL, NULL, true, false),
  ('wing_thorns', 'Wing Thorns', 'transmutation', NULL, 'poison', 3, 'both', 'alchemist 3, antipaladin 3, bloodrager 3, druid 3, magus 4, shaman 3, witch 3', '1 standard action', 'personal', 'you', NULL, NULL, '1 round/level', NULL, NULL, 'Your wings sprout poisonous thorns each the size of a dagger.', NULL, NULL, false, false),
  ('winged_sword', 'Winged Sword', 'transmutation', NULL, NULL, 2, 'both', 'bloodrager 2, inquisitor 3, magus 2, occultist 2, paladin 2, sorcerer/wizard 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one melee weapon', NULL, NULL, '10 minutes/level', 'Will negates (harmless, object)', 'yes (harmless, object)', 'The weapon targeted by this spell grows small feathered wings. For the duration of the spell, the weapon acts as if it had the throwing weapon special ability. This spell can be used in place of magic stone as a prerequisite for the throwing weapon special ability.', NULL, NULL, false, false),
  ('winter_feathers', 'Winter Feathers', 'abjuration', NULL, NULL, 1, 'both', 'bloodrager 1, cleric 1, druid 1, inquisitor 1, ranger 1, sorcerer/wizard 1', '1 standard action', 'touch', 'feathered creature touched', NULL, NULL, '24 hours', 'Will negates (harmless)', 'yes (harmless)', 'The target’s feathers thicken and fluff up to ward against winter’s chill. The target suffers no harm from being in a cold environment, and can exist comfortably in conditions as low as –50 degrees Fahrenheit without having to make Fortitude saves. The creature’s equipment is likewise protected. This spell doesn’t provide any protection from cold damage, nor does it protect against other environmental hazards associated with cold weather (such as slipping on ice, blindness from snow, and so on).', NULL, NULL, false, false),
  ('winter_s_grasp', 'Winter’s Grasp', 'conjuration', 'creation', 'cold, water', 2, 'both', 'druid 2, shaman 2, witch 2', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, '20-ft.-radius spread', NULL, '1 round/level', 'none', 'no', 'Ice encrusts the ground, radiating supernatural cold and making it hard for creatures to maintain their balance. This icy ground is treated as normal ice, forcing creatures to spend 2 squares of movement to enter an icy square and increasing the DC of Acrobatics checks in the area by 5. A creature that begins its turn in the affected area takes 1d6 points of cold damage and takes a –2 penalty on saving throws against spells with the cold descriptor for 1 round.', 'ground glass', NULL, true, false),
  ('wish', 'Wish', 'universal', NULL, NULL, 9, 'arcane', 'sorcerer/wizard 9; Bloodline arcane 9, div 9, djinni 9, draconic 9, efreeti 9', '1 standard action', 'see text', NULL, 'see text', NULL, 'see text', 'none, see text', 'yes', 'Wish is the mightiest spell a wizard or sorcerer can cast. By simply speaking aloud, you can alter reality to better suit you. Even wish, however, has its limits. A wish can produce any one of the following effects.', 'diamond worth 25,000 gp', NULL, false, true),
  ('with_the_wind', 'With the Wind', 'abjuration', NULL, 'air', 2, 'both', 'bloodrager 2, druid 2, magus 2, occultist 2, ranger 2, sorcerer/wizard 2, spiritualist 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', 'one creature', NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'You create eddies in the air around the subject that protect it from being checked or blown away. The target can’t be moved by winds of less than windstorm force unless it wishes to be.', NULL, NULL, false, false),
  ('withdraw_affliction', 'Withdraw Affliction', 'necromancy', NULL, NULL, 5, 'both', 'psychic 6, shaman 6, spiritualist 5, witch 7', '1 standard action', 'touch', 'one afflicted creature', NULL, NULL, 'instantaneous', 'none', 'yes', 'You push your hand into the subject, then withdraw an affliction from the body of the sufferer as a tangible object.', NULL, NULL, false, false),
  ('wither_limb', 'Wither Limb', 'necromancy', NULL, NULL, 5, 'both', 'cleric 6, inquisitor 6, shaman 6, sorcerer/wizard 6, spiritualist 5, witch 6', '1 standard action', 'touch', 'living creature touched', NULL, NULL, 'instantaneous', 'Fort negates', 'yes', 'You cause one limb of the target to shrivel and weaken. The target takes 2d6 points of damage. The points are permanently lost until the target’s limb is restored by heal, limited wish, miracle, regenerate, or wish. Wither limb affects only living creatures of the humanoid or monstrous humanoid type, or similar bipedal creatures at the GM’s discretion. You choose the limb affected.', NULL, NULL, false, false),
  ('witness', 'Witness', 'divination', 'scrying', NULL, 3, 'both', 'bard 3, inquisitor 3, medium 3, mesmerist 3, occultist 3, psychic 3, witch 3', '1 standard action', 'long (400 ft. + 40 ft./level)', 'one living creature', NULL, NULL, '1 minute/level (D)', 'Will negates (harmless)', 'yes (harmless)', 'You link your senses to the target, allowing you to see and hear through its eyes and ears. As a move action you can shift your senses from yourself to the target or back again. When using the target’s senses, you are blind and deaf. When perceiving through the target, you use its normal and special senses (such as darkvision), not your own.', NULL, NULL, false, false),
  ('wizened_appearance', 'Wizened Appearance', 'transmutation', 'polymorph', NULL, 1, 'arcane', 'alchemist 1, bard 1, medium 1, mesmerist 1, occultist 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', 'Fort negates', 'yes', 'You polymorph your target to look like an older version of itself.', NULL, NULL, false, false),
  ('wood_shape', 'Wood Shape', 'transmutation', NULL, NULL, 2, 'divine', 'druid 2, shaman 2; Domain  artifice 2', '1 standard action', 'touch', 'one touched piece of wood no larger than 10 cu. ft. + 1 cu. ft./level', NULL, NULL, 'instantaneous', 'Will negates (object)', 'yes (object)', 'Wood shape enables you to form one existing piece of wood into any shape that suits your purpose. While it is possible to make crude coffers, doors, and so forth, fine detail isn’t possible. There is a 30% chance that any shape that includes moving parts simply doesn’t work.', NULL, NULL, true, false),
  ('wooden_phalanx', 'Wooden Phalanx', 'conjuration', 'creation', NULL, 9, 'both', 'cleric/oracle 9, sorcerer/wizard 9; Mystery wood 9', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'three or more wood golems, no two of which can be more than 30 ft. apart (see text)', '1 hour/level (D)', 'none', 'no', 'You create 1d4+2 wood golems with the advanced template. The golems willingly aid you in combat or battle, perform a specific mission, or serve as bodyguards. You can only have one wooden phalanx spell in effect at one time. If you cast this spell while another casting is still in effect, the previous casting is dispelled.', NULL, NULL, false, false),
  ('wooden_wing_shield', 'Wooden Wing Shield', 'transmutation', NULL, NULL, 4, 'both', 'bloodrager 4, druid 4, magus 5, shaman 4, summoner 4', '1 immediate action', 'personal', 'you', NULL, NULL, '1 round/level or until you move', NULL, NULL, 'Your wings transmute into a wooden barrier resembling a tower shield to block attacks, granting you a +4 shield bonus to AC. If you move, the spell ends immediately.', NULL, NULL, false, false),
  ('woodland_rune', 'Woodland Rune', 'abjuration', NULL, NULL, 3, 'both', 'druid 3, ranger 3, shaman 3, witch 3', '10 minutes', '0 ft.; see text', NULL, NULL, NULL, 'permanent until discharged (D)', 'Fort negates', 'yes', 'Created by Ghorus as a safety measure to limit his enemies’ movements, this spell allows you to inscribe a powerful rune on any surface. Woodland rune triggers when any non-plant creature (apart from the caster) moves within 30 feet of the rune. When it’s triggered, roots and branches sprout from the ground, catching all creatures within a 30-foot burst of the rune and hindering their movement as if they were moving through heavy undergrowth, though it does not provide concealment. Plant creatures and creatures under the effect of woodland stride or freedom of movement are not affected by this spell. In all other respects, this spell functions as symbol of death.', NULL, NULL, false, false),
  ('word_of_beckoning', 'Word of Beckoning', 'conjuration', 'teleportation', NULL, 7, 'arcane', 'psychic 7, sorcerer/wizard 7', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'This spell functions like sending, except the subject also receives knowledge of a command word that, when spoken, summons you to the open space nearest to the subject.', NULL, NULL, false, false),
  ('word_of_chaos', 'Word of Chaos', 'evocation', NULL, 'chaotic, sonic', 7, 'divine', 'cleric/oracle 7, inquisitor 6; Domain chaos 7', '1 standard action', '40 ft.', NULL, 'non-chaotic creatures in a 40-ft.-radius spread centered on you', NULL, 'instantaneous', 'none or Will negates; see text', 'yes', 'Any non-chaotic creature within the area of a word of chaos spell suffers the following ill effects, depending on their HD.', NULL, NULL, false, false),
  ('word_of_recall', 'Word of Recall', 'conjuration', 'teleportation', NULL, 6, 'divine', 'cleric/oracle 6, druid 8', '1 standard action', 'unlimited', 'you and touched objects or other willing creatures', NULL, NULL, 'instantaneous', 'none or Will negates (harmless, object)', 'no or yes (harmless, object)', 'Word of recall teleports you instantly back to your sanctuary when the word is uttered. You must designate the sanctuary when you prepare the spell, and it must be a very familiar place. The actual point of arrival is a designated area no larger than 10 feet by 10 feet. You can be transported any distance within a plane but cannot travel between planes. You can transport, in addition to yourself, any objects you carry, as long as their weight doesn’t exceed your maximum load. You may also bring one additional willing Medium or smaller creature (carrying gear or objects up to its maximum load) or its equivalent per three caster levels. A Large creature counts as two Medium creatures, a Huge creature counts as two Large creatures, and so forth. All creatures to be transported must be in contact with one another, and at least one of those creatures must be in contact with you. Exceeding this limit causes the spell to fail.', NULL, NULL, false, false),
  ('word_of_resolve', 'Word of Resolve', 'abjuration', NULL, NULL, 1, 'divine', 'paladin 1', '1 immediate action', 'close (25 ft. + 5 ft./2 levels)', 'one ally', NULL, NULL, 'instantaneous', 'Will negate (harmless)', 'yes (harmless)', 'You focus your aura on one ally, allowing it to reroll a failed saving throw against a charm or fear effect with a +4 sacred bonus. If you do not have the aura of courage class ability, this spell has no effect on the target’s fear. If you do not have the aura of resolve class ability, this spell has no effect on any charm effects on the target.', NULL, NULL, true, false),
  ('world_wave', 'World Wave', 'transmutation', NULL, 'earth, water', 9, 'both', 'druid 9, sorcerer/wizard 9; Subdomain exploration 9; Bloodline aquatic 9; Elemental School earth 9, water 9; Mystery nature 9', '1 standard action', 'see text', NULL, NULL, NULL, '1 round/level or 1 hour/level; see text (D)', 'none', 'yes', 'You cause any sort of natural terrain (including water, forest, desert, tundra, and so on) to surge beneath your feet and safely propel you with devastating force over great distances. This wave of terrain undulates as it passes over the world, harmlessly lifting or stretching objects, creatures, and phenomena with a connection to nature but tearing through and damaging anything else it encounters. When you cast the spell you must choose the wave’s type, either a tsunami or a swell. If you choose a tsunami, you create a 30-foot-high tidal wave of earth or water hurtling across the landscape that lasts for 1 round per level. If you choose a swell, you create a more controlled and gentle 5-foot-high wave that lasts for 1 hour per level. Regardless of its form or composition, the crest of the wave extends 10 feet in front of and behind you, and 5 feet per level to both your left and right. You can stand or sit on the crest of this wave without any fear of falling off it and can even lie down and sleep (or take any other actions you could take if standing on solid ground) as it travels. You can grant up to one additional creature per level the ability to safely accompany you on this wave.', NULL, NULL, true, false),
  ('wracking_ray', 'Wracking Ray', 'necromancy', NULL, 'evil, pain', 5, 'arcane', 'sorcerer/wizard 5, witch 5', '1 standard action', 'medium (100 ft. + 10 ft./level)', NULL, NULL, 'ray', 'instantaneous', 'Fortitude half', 'yes', 'A ray of sickly greenish-gray negative energy issues forth from the palm of your hand.', 'an old bone, broken in the casting', NULL, false, false),
  ('wrath', 'Wrath', 'enchantment', 'compulsion', 'emotion, mind-affecting', 1, 'divine', 'inquisitor 1', '1 standard action', 'personal', NULL, NULL, NULL, '1 minute', NULL, NULL, 'You focus your anger against an enemy. Choose one enemy creature that you can see. You gain a +1 morale bonus on attack rolls and weapon damage rolls against that designated creature for every three caster levels you have (at least +1, maximum +3). You also receive this bonus on caster level checks made to overcome the creature’s Spell Resistance, if any. At 12th level, you gain the benefits of the Improved Critical feat on attack rolls made against the designated creature. This effect doesn’t stack with any other effect that expands the threat range of a weapon.', 'a thorny vine', NULL, false, false),
  ('wrathful_mantle', 'Wrathful Mantle', 'evocation', NULL, 'force, light', 2, 'divine', 'cleric/oracle 3, paladin 3; Subdomain hatred 2', '1 standard action', 'touch or 5 ft.; see text', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'A shimmering mantle of light shrouds the subject, light like a torch. The subject of the spell gains a +1 resistance bonus on all saving throws per four caster levels (maximum +5 at 20th level). The subject can end the wrathful mantle at any time as a swift action to deal 2d8 points of force damage to all creatures within 5 feet.', NULL, NULL, true, false),
  ('wrathful_weapon', 'Wrathful Weapon', 'transmutation', NULL, 'see text', 4, 'divine', 'cleric 4', '1 standard action', 'touch', 'melee weapon touched (see text)', NULL, NULL, '1 minute/level', 'Will (harmless, object)', 'yes (object)', 'You grant the targeted weapon one of the following weapon special abilities: anarchic, axiomatic, holy, or unholy. If anarchic, this spell has the chaos descriptor; if axiomatic, the law descriptor; if holy, the good descriptor; and if unholy, the evil descriptor. If the caster attempts to place a special ability on a weapon that already has that special ability, the spell fails.', NULL, NULL, true, false),
  ('wreath_of_blades', 'Wreath of Blades', 'abjuration', NULL, NULL, 4, 'arcane', 'bloodrager 4, magus 4, sorcerer/wizard 5, summoner/unchained summoner 5, witch 5', '1 standard action', 'personal', 'you', '5-foot-radius emanation centered on you', NULL, '1 round/level', 'Reflex half (special, see below)', 'no (special, see below)', 'The daggers serving as focus of this spell take on a deadly sharpness as they animate and spin around you, creating a 5-foot-radius emanation of spinning mithral blades that moves with you. Any creature that starts its turn within the area of the spinning blades takes 1d4 points of damage for every two caster levels (maximum 10d4 at 20th level) and the damage bypasses DR/silver. Furthermore, the daggers ward off some attacks, in a way similar to the warding weapon spell. While subject to this spell, you do not provoke attacks of opportunity for casting spells, even from creatures with the Disruptive feat. Creatures with the Spellbreaker feat can easily bypass this defensive property, though they still take damage from the spell. Your casting (even failing to cast defensively) still provokes attacks of opportunity from creatures with that feat. Lastly, the blades that serve as the focus for this spell can be enchanted for greater effect. When all of the blades share the same enhancement bonus and special weapon qualities, a creature that is damaged by this spell is also treated as if hit by one of these weapons. For example, if a 12th-level magus casts this spell using four +1 frost mithral daggers as focus, the damage dealt by the blades would be 6d4+1 plus 1d6 cold damage, as long as the daggers were commanded to be sheathed in ice. No matter the modifications made to the focus weapons, they must always be mithral daggers. No other type of weapons can serve as a focus for this spell.', NULL, 'four mithral daggers, each worth at least 502 gp each', false, true),
  ('yellow_sign', 'Yellow Sign', 'enchantment', 'compulsion', 'mind-affecting', 6, 'both', 'arcanist 9, bard 6, cleric/oracle 9, skald 6, sorcerer/wizard 9, witch 9', '10 minutes', '0 ft.; see text', NULL, NULL, NULL, 'see text', 'Will negates', 'yes', 'This spell functions as per symbol of death, save that creatures that succumb to this spell become dominated (as per dominate monster) by Hastur. This causes such creatures to seek to aid any obvious minions or worshipers of Hastur in sight, and any true worshiper of Hastur can command the affected creatures as if that worshiper had been the one to dominate them. In the case of conflicting commands issued from different true worshipers of Hastur, the commanders must attempt opposed Charisma checks, with the winner being able to command the targets for that round. If no worshipers or agents of Hastur are in sight, an affected creature can act normally. When affected by this spell’s Yellow Sign in this way, the effects last for 1 round per level. Once triggered, the Yellow Sign remains active for 10 minutes per caster level.', 'ochre and sulfur, plus powdered gold worth a total of 15,000 gp', NULL, false, true),
  ('youthful_appearance', 'Youthful Appearance', 'transmutation', 'polymorph', NULL, 1, 'arcane', 'alchemist 1, bard 1, psychic 1, sorcerer/wizard 1, witch 1', '1 standard action', 'touch', 'creature touched', NULL, NULL, '1 hour/level', NULL, NULL, 'You make your target look like a younger version of itself. You select how much younger it looks (for example, “10 years” or “as a young adult”). You cannot otherwise change details of the target’s appearance other than those directly associated with aging (for example, gray hair returns to its original color). The target cannot appear so much younger that it changes size. This spell does not affect any age-based modifications to ability scores or other age-related effects.', NULL, NULL, false, false),
  ('zephyr_s_fleetness', 'Zephyr’s Fleetness', 'transmutation', NULL, 'air', 3, 'divine', 'ranger 3', '1 round', 'long (400 ft. + 40 ft./level)', NULL, NULL, NULL, '1 minute/level', 'Will negates (harmless)', 'yes (harmless)', 'You can call upon the spirits of the air to grant agility to your allies. Each target gains a +30 foot enhancement bonus to its land speed and fly speed (if any). Each target can also move (and charge) through difficult terrain without penalty.', NULL, NULL, false, false),
  ('zone_of_foul_flames', 'Zone of Foul Flames', 'transmutation', NULL, NULL, 4, 'divine', 'druid 4', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius spread', NULL, '1 minute/level', 'Will negates', 'yes', 'This spell creates a zone where magical fire effects twist and lash out against those who create the effects. A zone of foul flames looks unremarkable to the casual observer, but a Perception check (DC = 20 + the caster’s level) reveals a faint rippling effect in the area, as if of heat distortions in the air.', 'a sliver of tree bark from a burnt tree', NULL, false, false),
  ('zone_of_silence', 'Zone of Silence', 'illusion', 'glamer', NULL, 4, 'arcane', 'bard 4', '1 round', 'personal', NULL, '5-ft.-radius emanation centered on you', NULL, '1 hour/level (D)', NULL, NULL, 'By casting zone of silence, you manipulate sound waves in your immediate vicinity so that you and those within the spell’s area can converse normally, yet no one outside can hear your voices or any other noises from within, including language-dependent or sonic spell effects. This effect is centered on you and moves with you. Anyone who enters the zone immediately becomes subject to its effects, but those who leave are no longer affected. Note, however, that a successful DC 20 Linguistics check to read lips can still reveal what’s said inside a zone of silence.', NULL, NULL, false, false),
  ('zone_of_truth', 'Zone of Truth', 'enchantment', 'compulsion', 'mind-affecting', 2, 'both', 'cleric/oracle 2, inquisitor 2, medium 2, paladin 2, psychic 2, witch 2; Subdomain honor 2', '1 standard action', 'close (25 ft. + 5 ft./2 levels)', NULL, '20-ft.-radius emanation', NULL, '1 min./level', 'Will negates', 'yes', 'Creatures within the emanation area (or those who enter it) can’t speak any deliberate and intentional lies. Each potentially affected creature is allowed a save to avoid the effects when the spell is cast or when the creature first enters the emanation area. Affected creatures are aware of this enchantment. Therefore, they may avoid answering questions to which they would normally respond with a lie, or they may be evasive as long as they remain within the boundaries of the truth. Creatures who leave the area are free to speak as they choose.', NULL, NULL, true, false)
